177: bool ResumableSm120Context::InitCilpMode()
178: {
179:     if (!EnsureHandles(-1) || handles_.hSubDevice == 0) {
180:         return false;
181:     }
182: 
183:     uint32_t target_h = handles_.hTsg ? handles_.hTsg : handles_.hChannel;
184:     if (target_h == 0) return false;
185: 
186:     // Step 1: Try COMPUTE_CILP (2), fallback to COMPUTE_CTA (1) via 0x20801210 (32-byte params)
187:     Nv2080CtrlGrSetCtxswPreemptionModeParams mode{};
188:     mode.flags           = 0x2u; // bit 1: set cilpPreemptMode (0x3u sets both gfxp & cilp)
189:     mode.hChannel        = target_h;
190:     mode.gfxpPreemptMode = 0;
191:     mode.cilpPreemptMode = 2u;   // NV2080_CTRL_SET_CTXSW_PREEMPTION_MODE_COMPUTE_CILP
192: 
193:     uint32_t st = RmControlCall(handles_.ctl_fd, handles_.hClient,
194:                                 handles_.hSubDevice, 0x20801210u,
195:                                 &mode, sizeof(mode));
196:     if (st != 0) {
197:         mode.flags           = 0x2u;
198:         mode.cilpPreemptMode = 1u; // NV2080_CTRL_SET_CTXSW_PREEMPTION_MODE_COMPUTE_CTA
199:         st = RmControlCall(handles_.ctl_fd, handles_.hClient,
200:                            handles_.hSubDevice, 0x20801210u,
201:                            &mode, sizeof(mode));
202:     }
203:     cilp_enabled_ = (st == 0);
204:     return cilp_enabled_;
205: }
