207: bool ResumableSm120Context::PreemptPulse()
208: {
209:     if (!EnsureHandles(-1)) {
210:         return false;
211:     }
212:     if (!cilp_enabled_) {
213:         InitCilpMode();
214:     }
215: 
216:     // Reduce TSG timeslice to minimum before preemption so runlist yields immediately
217:     NvA06cCtrlTimesliceParams ts{};
218:     ts.timesliceUs = 1;
219:     RmControlCall(handles_.ctl_fd, handles_.hClient,
220:                   handles_.hTsg, 0xa06c0103u, &ts, sizeof(ts));
221: 
222:     // Issue synchronous hardware TSG context-switch preemption (0xa06c0105)
223:     NvA06cCtrlPreemptParams pr{};
224:     pr.bWait          = 1;
225:     pr.bManualTimeout = 1;
226:     pr.timeoutUs      = 100000;
227:     uint32_t st = RmControlCall(handles_.ctl_fd, handles_.hClient,
228:                                 handles_.hTsg, 0xa06c0105u, &pr, sizeof(pr));
229:     return (st == 0);
