256:     if (dbg_suspended_ && handles_.hDebugger != 0) {
257:         uint32_t hc = handles_.hDebuggerClient ? handles_.hDebuggerClient : handles_.hClient;
258:         uint32_t dummy = 0;
259:         uint32_t st = RmControlCall(handles_.ctl_fd, hc,
260:                                     handles_.hDebugger, 0x83de0318u, &dummy, sizeof(dummy));
261:         dbg_suspended_ = false;
