103:     NVOS21 a; memcpy(&a, arg, sizeof a);
104:     if (a.status != 0 || a.hObject == 0) return;
105:     switch (a.hClass) {
106:     case CLASS_ROOT:
107:         if (H.fd < 0) H.fd = fd;
108:         if (!H.client) H.client = a.hObject;
109:         break;
110:     case CLASS_DEVICE:
111:         if (!H.device) { H.device = a.hObject; H.client = a.hRoot; H.fd = fd; }
112:         break;
113:     case CLASS_SUBDEV:
114:         if (!H.subdev) H.subdev = a.hObject;
115:         break;
116:     case CLASS_TSG:
117:         H.tsg = a.hObject;
118:         if (H.fd < 0) H.fd = fd;
119:         if (!H.client) H.client = a.hRoot;
120:         RecordToCtxTable(a.hClass, a.hObject, a.hRoot, fd);
121:         break;
122:     case CLASS_CHANNEL:
123:         H.channel = a.hObject;
124:         RecordToCtxTable(a.hClass, a.hObject, a.hRoot, fd);
125:         break;
126:     case CLASS_COMPUTE:
127:         if (H.ncompute < L3_TRAP_MAX_KGO) H.computes[H.ncompute++] = a.hObject;
128:         RecordToCtxTable(a.hClass, a.hObject, a.hRoot, fd);
129:         break;
130:     case CLASS_SMDBGSSN:
