361: // The driver traps kernels at launch once debugger parameters are set.  The
362: // sm120 handler has no benign path for such a trap, so try to turn the launch
363: // blocking off and keep only the explicit 0x83de0317 trap.
364: static void ClearDebuggerLaunchBlocking()
365: {
366:     if (getenv("XSCHED_SM120_TRAP_DBGFLAGS") == nullptr) return;
367:     void *h = nullptr;
368:     const char *paths[] = {"libcuda.so.1", "libcuda.so"};
369:     for (const char *p : paths) {
370:         h = dlopen(p, RTLD_NOW | RTLD_NOLOAD);
371:         if (h) break;
372:     }
373:     if (h == nullptr) { XWARN("sm120 trap: libcuda not found for debug flags"); return; }
374:     // Launch blocking makes every kernel launch wait for the debugger (the
375:     // replay saw cuLaunchKernel stall ~4.6 s), so switch it OFF; keep the
376:     // other two flags on.  Never touch cudbgAttachHandlerAvailable /
377:     // cudbgDebuggerCapabilities.
378:     int *lb = (int *)dlsym(h, "cudbgEnableLaunchBlocking");
379:     if (lb) { XINFO("sm120 trap: cudbgEnableLaunchBlocking = %d -> 0", *lb); *lb = 0; }
380:     const char *names[] = {"cudbgEnablePreemptionDebugging", "cudbgDebuggerInitialized"};
381:     for (const char *n : names) {
382:         int *v = (int *)dlsym(h, n);
383:         if (v) { XINFO("sm120 trap: %s = %d -> 1", n, *v); *v = 1; }
384:     }
385: }
