387: static void InitCudbg()
388: {
389:     if (getenv("XSCHED_SM120_TRAP_CUDBG") == nullptr) return;
390:     void *lc = dlopen("libcuda.so.1", RTLD_NOW | RTLD_NOLOAD);
391:     if (lc == nullptr) lc = dlopen("libcuda.so", RTLD_NOW | RTLD_NOLOAD);
392:     if (lc == nullptr) { XWARN("sm120 trap: libcuda not loaded for cudbg init"); return; }
393:     int (*init1)(int) = (int (*)(int))dlsym(lc, "cudbgApiInit");
394:     if (init1 == nullptr) { XWARN("sm120 trap: cudbgApiInit not exported"); return; }
395:     int mode = getenv("XSCHED_SM120_TRAP_CUDBG_MODE") ? atoi(getenv("XSCHED_SM120_TRAP_CUDBG_MODE")) : 1;
396:     int r = init1(mode);
397:     XINFO("sm120 trap: cudbgApiInit(%d) -> %d", mode, r);
398:     if (getenv("XSCHED_SM120_TRAP_CUDBG_ATTACH") != nullptr) {
399:         // cudbgApiAttach() drives the debugger-state transition cuda-gdb
400:         // performs on attach (contexts switched to the debug vtbl).  Without
401:         // it the driver suspends every new launch on a stop nobody answers.
402:         int (*attach)() = (int (*)())dlsym(lc, "cudbgApiAttach");
403:         if (attach == nullptr) { XWARN("sm120 trap: cudbgApiAttach not exported"); return; }
404:         int a = attach();
405:         XINFO("sm120 trap: cudbgApiAttach() -> %d", a);
406:     }
407: }
