424:         XWARN("sm120 trap: export tables unavailable");
425:         return false;
426:     }
427:     const void **tt = (const void **)tt_raw, **mt = (const void **)mt_raw;
428:     struct { uint64_t flags, ssize; void *handle; uint64_t stub, hsize, rsv; } ti;
429:     memset(&ti, 0, sizeof ti);
430:     if (((CUresult (*)(CUcontext, void *))tt[20])(T.ctx, &ti) != CUDA_SUCCESS || !ti.handle) {
431:         XWARN("sm120 trap: slot20 getter failed");
432:         return false;
433:     }
434:     CUdeviceptr pc = 0; uint64_t sz = 0;
435:     if (((CUresult (*)(CUcontext, void *, CUdeviceptr *))mt[24])(T.ctx, ti.handle, &pc) != CUDA_SUCCESS ||
436:         ((CUresult (*)(void *, uint64_t *))mt[25])(ti.handle, &sz) != CUDA_SUCCESS || sz < 0x1300) {
437:         XWARN("sm120 trap: slot20 image unavailable (pc=%#llx sz=%#llx)",
438:               (unsigned long long)pc, (unsigned long long)sz);
439:         return false;
440:     }
441:     std::vector<uint8_t> img;
442:     if (!ReadImageSlice(pc, sz, img)) { XWARN("sm120 trap: image read failed"); return false; }
443:     uint64_t trt = (uint64_t)Imm32At(&img[0x130]) | ((uint64_t)Imm32At(&img[0x140]) << 32);
444:     uint64_t base = trt - 0xc38300ULL;
445:     uint64_t live = base + 0x15f0f00ULL;
446: 
447:     std::vector<uint8_t> hdr;
448:     if (!ReadImageSlice(live, 0xa0, hdr)) { XWARN("sm120 trap: live handler read failed"); return false; }
449:     static const uint32_t fp[10] = {
450:         0x0000795c, 0x1a007956, 0xff007387, 0xff007387, 0xff007387,
451:         0x00047202, 0x00057202, 0xff067803, 0x17077355, 0xff007387,
452:     };
453:     for (int i = 0; i < 10; i++) {
454:         if (OpcodeAt(&hdr[i * 16]) != fp[i]) {
455:             XWARN("sm120 trap: live handler fingerprint mismatch at +%#x", i * 16);
456:             return false;
457:         }
458:     }
459: 
460:     uint64_t cave = pc + 0xa00;
461:     uint64_t tramp = cave + 0x80;
462:     const uint64_t exit_tramp[2] = {
463:         0x000000000000794dULL, 0x000fea0003800000ULL // EXIT (normal mode)
464:     };
465: 
466:     // return stub: displaced MOV R3,RZ + return to +0x3a0
467:     for (size_t off = 0; off < 0x80; off += 16) {
468:         T.ret_stub[off/8] = 0x0000000000007918ULL; T.ret_stub[off/8+1] = 0x000fc00000000000ULL;
469:         T.armed_stub[off/8] = 0x0000000000007918ULL; T.armed_stub[off/8+1] = 0x000fc00000000000ULL;
470:     }
471:     // Keep R2 (the reason mask) intact: zeroing it makes the handler skip
472:     // the real handling of a trap and re-execute the faulting instruction.
473:     T.ret_stub[0] = 0x000000ff00037202ULL; T.ret_stub[1] = 0x003ff00000000f00ULL; // MOV R3,RZ
474:     T.ret_stub[2] = 0x000000100c0c7835ULL; T.ret_stub[3] = 0x003fe600078e0000ULL; // IADD R12
475:     T.ret_stub[4] = 0x000000000c087950ULL; T.ret_stub[5] = 0x003fc00003a00000ULL; // RET
476: 
477:     // Reason-guarded armed stub (FINDINGS v4.3, unconditional default): only a
478:     // trap whose reason has bit0 (the explicit 0x83de0317 request; launch-time
479:     // traps carry 0x8) is redirected to the EXIT trampoline at cave+0x80.
480:     // Everything else takes the exact return path of the original handler.
481:     // LOP3 encoding is copied verbatim from the live handler (+0x3b0).
482:     if (getenv("XSCHED_SM120_TRAP_LEGACY_EXIT") == nullptr) {
483:         T.armed_stub[0] = ((uint64_t)(uint32_t)tramp << 32) | (20ULL << 16) | 0x00007802ULL;
484:         T.armed_stub[1] = 0x003fe20000000f00ULL;                          // MOV R20, lo
485:         T.armed_stub[2] = ((uint64_t)(uint32_t)(tramp >> 32) << 32) | (21ULL << 16) | 0x00007802ULL;
486:         T.armed_stub[3] = 0x003fe20000000f00ULL;                          // MOV R21, hi
487:         T.armed_stub[4] = 0x0000000102ff7812ULL; T.armed_stub[5] = 0x003fda000780c0ffULL; // LOP3 P0,RZ,R2,1
488:         T.armed_stub[6] = 0x0000000000048947ULL; T.armed_stub[7] = 0x003ff20003800000ULL; // @!P0 BRA +0x10
489:         T.armed_stub[8] = 0xffffa800ff147387ULL; T.armed_stub[9] = 0x0033e40000100a00ULL; // STL.64 [0xffffa8], R20
490:         T.armed_stub[10] = 0x000000ff00037202ULL; T.armed_stub[11] = 0x003ff00000000f00ULL; // MOV R3, RZ
491:         T.armed_stub[12] = 0x000000100c0c7835ULL; T.armed_stub[13] = 0x003fe600078e0000ULL; // IADD R12
492:         T.armed_stub[14] = 0x000000000c087950ULL; T.armed_stub[15] = 0x003fc00003a00000ULL; // RET.ABS.NODEC
493:         goto armed_ready;
494:     }
495:     // Legacy stub (only when XSCHED_SM120_TRAP_LEGACY_EXIT is set):
496:     T.armed_stub[0] = 0x00005c00ff047b82ULL; T.armed_stub[1] = 0x000fc00000000800ULL; // LDC R4,c[0x170]
497:     T.armed_stub[2] = 0x00005d00ff057b82ULL; T.armed_stub[3] = 0x000fc00000000800ULL; // LDC R5,c[0x174]
498:     T.armed_stub[4] = 0x00000000040a7980ULL; T.armed_stub[5] = 0x000ea20000100900ULL; // LD.E R10,[R4]
499:     T.armed_stub[6] = 0x000000ff0a00720cULL; T.armed_stub[7] = 0x004fda0003f05270ULL; // ISETP.NE.AND P0,R10,RZ
500:     T.armed_stub[8] = 0x000000000000094dULL; T.armed_stub[9] = 0x000fea0003800000ULL; // @P0 EXIT
501:     T.armed_stub[10] = 0x000000ff00037202ULL; T.armed_stub[11] = 0x003ff00000000f00ULL; // MOV R3,RZ
502:     T.armed_stub[12] = 0x000000100c0c7835ULL; T.armed_stub[13] = 0x003fe600078e0000ULL; // IADD R12
503:     T.armed_stub[14] = 0x000000000c087950ULL; T.armed_stub[15] = 0x003fc00003a00000ULL; // RET
504: armed_ready:;
505: 
506:     // CALL.ABS (T-0x100)>>8 at handler+0x390
507:     std::vector<uint8_t> orig;
508:     if (!ReadImageSlice(live + 0x380, 16, orig)) return false;
509:     uint64_t o0, o1; memcpy(&o0, &orig[0], 8); memcpy(&o1, &orig[8], 8);
510:     uint64_t enc = (cave - 0x100) >> 8;
511:     uint64_t call[2] = {
512:         ((enc & 0xffffffffULL) << 32) | (o0 & 0xffffffffULL),
513:         (o1 & ~0xffULL) | ((enc >> 32) & 0xffULL),
514:     };
515: 
516:     {
517:         std::vector<uint8_t> orig390;
518:         if (!ReadImageSlice(live + 0x390, 16, orig390)) return false;
519:         memcpy(T.orig_390, orig390.data(), 16);
520:     }
521:     T.call_words[0] = call[0]; T.call_words[1] = call[1];
522:     T.handler_va = live; T.cave_va = cave; T.live_base = base;
523:     T.drv_preempt_buf = base - 0x2000000ULL;
524:     T.scratch_buf = base + 0x1a00000ULL;
525:     XINFO("sm120 trap: live_base=%#llx driver preempt_buf=%#llx scratch=%#llx (handler reads +4/+8)",
526:           (unsigned long long)base, (unsigned long long)T.drv_preempt_buf,
527:           (unsigned long long)T.scratch_buf);
528:     if (getenv("XSCHED_SM120_TRAP_DUMP_READ") != nullptr) {
529:         // Dump the live do_read_trap_reason and print every MOV-imm32, so we
530:         // can recover the driver-patched preemption-buffer address
531:         // (CUDA_PREEMPTION_BUFFER_PATCH_ADDR).
532:         uint64_t rd_va = base + 0x15f2100ULL;
533:         std::vector<uint8_t> rd(0x600);
534:         if (ReadImageSlice(rd_va, rd.size(), rd)) {
535:             uint32_t imm120 = 0, imm130 = 0;
536:             bool have120 = false, have130 = false;
537:             for (size_t o = 0; o + 16 <= rd.size(); o += 16) {
538:                 uint64_t w0, w1; memcpy(&w0, &rd[o], 8); memcpy(&w1, &rd[o + 8], 8);
539:                 if ((w0 & 0xffffULL) == 0x7802ULL) {
540:                     uint32_t imm = (uint32_t)(w0 >> 32);
541:                     uint32_t reg = (uint32_t)((w0 >> 16) & 0xff);
542:                     if (o == 0x120) { imm120 = imm; have120 = true; }
543:                     if (o == 0x130) { imm130 = imm; have130 = true; }
544:                     if (imm != 0) {
545:                         XINFO("sm120 trap: do_read+%#zx MOV R%u, %#x", o, reg, imm);
546:                     }
547:                 }
548:                 (void)w1;
549:             }
550:             // The driver may relocate the preemption buffer when the debugger
551:             // session is created.  do_read+0x120/0x130 are MOV low/high of the
552:             // patched pbuf address; use the post-session value if it changed.
553:             if (have120 && have130) {
554:                 uint64_t np = (uint64_t)imm120 | ((uint64_t)imm130 << 32);
555:                 if (np != 0 && np != T.drv_preempt_buf) {
556:                     XINFO("sm120 trap: pbuf relocated by session: %#llx -> %#llx",
557:                           (unsigned long long)T.drv_preempt_buf,
558:                           (unsigned long long)np);
559:                     T.drv_preempt_buf = np;
560:                 } else if (np != 0) {
561:                     XINFO("sm120 trap: pbuf immediate %#llx (same as base-0x2000000)",
562:                           (unsigned long long)np);
563:                 }
564:             }
