566:                 for (size_t o = 0x100; o < 0x200; o += 16) {
567:                     uint64_t w0, w1; memcpy(&w0, &rd[o], 8); memcpy(&w1, &rd[o + 8], 8);
568:                     XINFO("sm120 trap: do_read raw +%#zx: %016llx %016llx", o,
569:                           (unsigned long long)w0, (unsigned long long)w1);
570:                 }
571:             }
572:         } else {
573:             XWARN("sm120 trap: cannot read do_read_trap_reason at %#llx",
574:                   (unsigned long long)rd_va);
575:         }
576:     }
577:     if (getenv("XSCHED_SM120_TRAP_DUMP_ACCESS") != nullptr) {
578:         uint32_t dv = 0;
579:         CUresult rr = Driver::MemcpyDtoH_v2(&dv, T.drv_preempt_buf + 4, sizeof dv);
580:         uint32_t one = 2, back = 0;
581:         size_t hw = cuXtraMemcpyHtoD(T.drv_preempt_buf + 4, &one, sizeof one, T.stream);
582:         cuXtraMemcpyDtoH(&back, T.drv_preempt_buf + 4, sizeof back, T.stream);
583:         XINFO("sm120 trap: drv_pbuf access: dtoh r=%d val=%#x; xtra htod w=%zu back=%#x",
584:               (int)rr, dv, hw, back);
