597:         size_t wt = cuXtraMemcpyHtoD(tramp, exit_tramp, sizeof exit_tramp, T.stream);
598:         size_t w1 = cuXtraMemcpyHtoD(live + 0x390, call, 16, T.stream);
599:         cuXtraInvalInstrCache(T.ctx);
600:         uint64_t rb[2] = {0, 0};
601:         cuXtraMemcpyDtoH(rb, live + 0x390, 16, T.stream);
602:         bool ok = w0 == sizeof T.ret_stub && wt == sizeof exit_tramp && w1 == 16 && rb[0] == call[0] && rb[1] == call[1];
603:         XINFO("sm120 trap: live=%#llx cave=%#llx tramp=%#llx always-armed=%s",
604:               (unsigned long long)live, (unsigned long long)cave,
605:               (unsigned long long)tramp, ok ? "ok" : "FAILED");
606:         return ok;
607:     }
608:     if (getenv("XSCHED_SM120_TRAP_PROBE_ONLY") != nullptr) {
609:         XINFO("sm120 trap: live=%#llx cave=%#llx tramp=%#llx (probe only)",
610:               (unsigned long long)live, (unsigned long long)cave,
611:               (unsigned long long)tramp);
612:         return true;
613:     }
614:     // Default: install the call site now, before any kernel runs.  Rewriting
615:     // the call site while kernels run blocks in the driver (it is executing
616:     // code), while the cave can still be switched at runtime -- this is the
617:     // same split run_l3kill.sh relies on.
618:     InitWriter();
619:     if (ArmAtTrigger()) {
620:         // Arm() swaps this in *after* the launch (and before the 0x83de
621:         // session exists), so the only trap it sees is the explicit 0317.
622:         // The cave reads one 32-bit word of the driver's preemption buffer
623:         // with the handler's own LD.E.CONSTANT and records it in wr_buf, so
624:         // the host can read it without touching the driver VA.  The sentinel
625:         // variant stores R2 (reason mask) instead, proving the cave ran.
626:         bool sentinel = getenv("XSCHED_SM120_TRAP_ARM_SENTINEL") != nullptr;
627:         bool wr_probe = getenv("XSCHED_SM120_TRAP_ARM_PBUF_WRITE") != nullptr;
628:         uint64_t off = getenv("XSCHED_SM120_TRAP_DRVBUF_OFF")
629:                      ? strtoull(getenv("XSCHED_SM120_TRAP_DRVBUF_OFF"), nullptr, 0) : 4ULL;
630:         uint64_t tva = T.drv_preempt_buf + off;
631:         uint64_t buf = T.rec_dev ? T.rec_dev + 0x100 : T.wr_buf + 0x100;
632:         T.armed_stub[0] = (((uint64_t)(uint32_t)buf) << 32) | (8ULL << 16) | 0x00007802ULL;
633:         T.armed_stub[1] = 0x003fe20000000f00ULL;                                  // MOV R8, buf lo
634:         T.armed_stub[2] = (((uint64_t)(uint32_t)(buf >> 32)) << 32) | (9ULL << 16) | 0x00007802ULL;
635:         T.armed_stub[3] = 0x003fe20000000f00ULL;                                  // MOV R9, buf hi
636:         if (wr_probe) {
637:             // Can the trap write the driver's preemption buffer?  With
638:             // WValue=0 store R2 (the 0317 reason, 0x1); otherwise store the
639:             // given command word (2 = preempt_save), which the handler's next
640:             // dispatch-loop iteration would pick up as 0x10|0x20.
641:             uint32_t wval = getenv("XSCHED_SM120_TRAP_ARM_PBUF_WVAL")
642:                           ? (uint32_t)strtoul(getenv("XSCHED_SM120_TRAP_ARM_PBUF_WVAL"),
643:                                               nullptr, 0) : 0;
644:             T.armed_stub[4] = (((uint64_t)(uint32_t)tva) << 32) | (6ULL << 16) | 0x00007802ULL;
645:             T.armed_stub[5] = 0x003fe20000000f00ULL;                              // MOV R6, tva lo
646:             T.armed_stub[6] = (((uint64_t)(uint32_t)(tva >> 32)) << 32) | (7ULL << 16) | 0x00007802ULL;
647:             T.armed_stub[7] = 0x003fe20000000f00ULL;                              // MOV R7, tva hi
648:             if (wval == 0) {
649:                 T.armed_stub[8] = 0x0000000006027385ULL; T.armed_stub[9] = 0x000fe20000100902ULL;  // ST.E [R6],R2
650:                 T.armed_stub[10] = 0x0000000008027385ULL; T.armed_stub[11] = 0x000fe20000100902ULL; // ST.E [R8],R2
651:             } else {
652:                 T.armed_stub[8] = (((uint64_t)wval) << 32) | (10ULL << 16) | 0x00007802ULL;
653:                 T.armed_stub[9] = 0x003fe20000000f00ULL;                          // MOV R10, wval
654:                 T.armed_stub[10] = 0x00000000060a7385ULL; T.armed_stub[11] = 0x000fe2000010090aULL; // ST.E [R6],R10
655:             }
656:             T.armed_stub[12] = 0x000000100c0c7835ULL; T.armed_stub[13] = 0x003fe600078e0000ULL; // IADD R12
657:             T.armed_stub[14] = 0x000000000c087950ULL; T.armed_stub[15] = 0x003fc00003a00000ULL; // RET
658:         } else if (sentinel) {
