34: // Unmodified low-priority compute kernel: contains ZERO cooperative host-flag polling.
35: // Hardware trap/preemption is driven externally by TrapSm120Context::Trigger().
36: __global__ void LpHardwarePreemptKernel(float *__restrict__ out,
37:                                         const float *__restrict__ in,
38:                                         int n,
39:                                         uint64_t target_ns,
40:                                         uint64_t *__restrict__ d_kernel_t0,
41:                                         uint32_t *__restrict__ d_started,
42:                                         int use_shmem_barriers)
43: {
44:     __shared__ float s_buf[256];
45:     int tid = blockIdx.x * blockDim.x + threadIdx.x;
46: 
47:     if (threadIdx.x == 0) {
48:         uint64_t now = ReadGlobalTimerNs();
49:         atomicCAS(reinterpret_cast<unsigned long long *>(d_kernel_t0),
50:                   0ULL, static_cast<unsigned long long>(now));
51:         atomicExch(d_started, 1U);
52:     }
53:     __syncthreads();
54: 
55:     uint64_t k_t0 = *reinterpret_cast<volatile uint64_t *>(d_kernel_t0);
56:     if (k_t0 == 0ULL) {
57:         k_t0 = ReadGlobalTimerNs();
58:     }
59: 
60:     float acc = (tid < n) ? in[tid] : 1.0f;
61:     if (use_shmem_barriers) {
62:         s_buf[threadIdx.x & 255] = acc;
63:         __syncthreads();
64:     }
65: 
66:     while ((ReadGlobalTimerNs() - k_t0) < target_ns) {
67:         acc = acc * 1.0000001f + 0.0000001f;
68:         if (use_shmem_barriers) {
69:             s_buf[threadIdx.x & 255] = acc;
70:             __syncthreads();
71:             acc = s_buf[(threadIdx.x + 1) & 255];
72:         }
73:     }
74: 
75:     for (int idx = tid; idx < n; idx += gridDim.x * blockDim.x) {
76:         float v = in[idx];
77:         out[idx] = (v * 2.5f + 1.25f) + (acc * 0.0f);
78:     }
79: }
