96: static int FindNvidiaCtlFd()
97: {
98:     DIR *d = opendir("/proc/self/fd");
99:     if (!d) return -1;
100:     struct dirent *de;
101:     int found = -1;
102:     while ((de = readdir(d)) != nullptr) {
103:         if (de->d_name[0] == '.') continue;
104:         char path[256];
105:         char link[256];
106:         std::snprintf(path, sizeof(path), "/proc/self/fd/%s", de->d_name);
107:         ssize_t len = readlink(path, link, sizeof(link) - 1);
108:         if (len > 0) {
109:             link[len] = '\0';
110:             if (std::strstr(link, "/dev/nvidiactl") != nullptr) {
111:                 found = std::atoi(de->d_name);
112:                 break;
113:             }
114:         }
115:     }
116:     closedir(d);
117:     return found;
118: }
