1197:         rec[2] = ((uint64_t)(uint32_t)((T.wr_buf + 0x100) >> 32) << 32) | (9ULL << 16) | 0x00007802ULL;
1198:         rec[3] = 0x003fe20000000f00ULL;                                  // MOV R9, hi
1199:         rec[4] = 0x0000000008027385ULL;                                  // ST.E [R8], R2
1200:         rec[5] = 0x000fe20000100900ULL;
1201:         rec[6] = 0x000000ff00037202ULL; rec[7] = 0x003ff00000000f00ULL;  // MOV R3,RZ
1202:         rec[8] = 0x000000100c0c7835ULL; rec[9] = 0x003fe600078e0000ULL;  // IADD R12
1203:         rec[10] = 0x000000000c087950ULL; rec[11] = 0x003fc00003a00000ULL; // RET
1204:         size_t w0 = cuXtraMemcpyHtoD(cave, rec, sizeof rec, T.stream);
1205:         size_t w1 = cuXtraMemcpyHtoD(live + 0x390, call, 16, T.stream);
1206:         cuXtraInvalInstrCache(T.ctx);
1207:         XINFO("sm120 trap: reason probe installed w=%zu/%zu buf=%#llx",
1208:               w0, w1, (unsigned long long)(T.wr_buf + 0x100));
1209:         return w0 == sizeof rec && w1 == 16;
1210:     }
1211:     // The cave is armed *before* the first launch: at level 3 the guardian
1212:     // spins waiting for the trap, so the GPU is fully occupied and neither a
1213:     // host copy nor a device writer can run once the kernels are up.
1214:     bool pre_arm = getenv("XSCHED_SM120_TRAP_PRE_RETURN") == nullptr && !ArmAtTrigger();
1215:     const uint64_t *stub = pre_arm ? T.armed_stub : T.ret_stub;
1216:     size_t w0 = cuXtraMemcpyHtoD(cave, stub, sizeof T.ret_stub, T.stream);
1217:     size_t wt = cuXtraMemcpyHtoD(tramp, exit_tramp, sizeof exit_tramp, T.stream);
1218:     size_t w1 = cuXtraMemcpyHtoD(live + 0x390, call, 16, T.stream);
1219:     cuXtraInvalInstrCache(T.ctx);
1220:     uint64_t rb[2] = {0, 0};
1221:     cuXtraMemcpyDtoH(rb, live + 0x390, 16, T.stream);
1222:     bool ok = w0 == sizeof T.ret_stub && wt == sizeof exit_tramp && w1 == 16 && rb[0] == call[0] && rb[1] == call[1];
1223:     XINFO("sm120 trap: live=%#llx cave=%#llx tramp=%#llx patched=%s (%s)",
1224:           (unsigned long long)live, (unsigned long long)cave,
1225:           (unsigned long long)tramp, ok ? "ok" : "FAILED", pre_arm ? "armed" : "return");
1226:     return ok;
1227: }
