1341:                 close(fd);
1342:                 if (T.shm == MAP_FAILED) T.shm = nullptr;
1343:             } else if (fd >= 0) {
1344:                 close(fd);
1345:             }
1346:             if (T.shm != nullptr) {
1347:                 memset(T.shm, 0, sizeof *T.shm);
1348:                 T.shm->pid = (uint32_t)getpid();
1349:                 if (agent_cfg && *agent_cfg) {
