1351:                     if (pid == 0) {
1352:                         execl(agent_cfg, agent_cfg, T.shm_name, (char *)nullptr);
1353:                         _exit(127);
1354:                     }
1355:                     T.agent_pid = (int)pid;
1356:                 }
1357:                 for (int i = 0; i < 100 && T.shm->agent_ready == 0; i++) usleep(5000);
1358:                 if (H.client && H.device && T.shm->agent_ready) {
1359:                     struct { uint32_t target, rights, type; } p;
1360:                     p = { H.client, 1, 0x0002 };
1361:                     T.shm->policy_status[0] = rm_control(H.fd, H.client, H.client, 0xd04, &p, sizeof p);
1362:                     p = { H.client, 4, 0x40002 };
1363:                     T.shm->policy_status[1] = rm_control(H.fd, H.client, H.client, 0xd04, &p, sizeof p);
1364:                     p = { T.shm->agent_client, 1, 0x40003 };
1365:                     T.shm->policy_status[2] = rm_control(H.fd, H.client, H.client, 0xd04, &p, sizeof p);
1366:                     T.shm->app_client = H.client;
