1370:                     T.shm->ncompute = H.ncompute < L3_TRAP_MAX_KGO ? H.ncompute : L3_TRAP_MAX_KGO;
1371:                     for (uint32_t i = 0; i < T.shm->ncompute; i++) T.shm->computes[i] = H.computes[i];
1372:                     __sync_synchronize();
