30: /// \brief Minimal cuda-gdb MI client.
31: ///
32: /// cuda-gdb 13.2 has no Python and its MI state tracking is fragile right after
33: /// attach, so the commands are paced and the result records are matched
34: /// explicitly instead of relying on the MI state machine.
35: class MiClient
36: {
37: public:
38:     ~MiClient() { Kill(); }
39: 
40:     bool Spawn()
41:     {
42:         int in[2], out[2];
43:         if (pipe(in) || pipe(out)) return false;
44:         pid_ = fork();
45:         if (pid_ < 0) return false;
46:         if (pid_ == 0) {
47:             dup2(in[0], 0); dup2(out[1], 1); dup2(out[1], 2);
48:             close(in[0]); close(in[1]); close(out[0]); close(out[1]);
49:             execlp("cuda-gdb", "cuda-gdb", "--interpreter=mi2", "-q", "-nx", nullptr);
50:             _exit(127);
51:         }
52:         close(in[0]); close(out[1]);
53:         to_ = in[1]; from_ = out[0];
54:         return WaitFor("(gdb)", 30.0);
55:     }
56: 
57:     bool Attach(pid_t pid)
58:     {
59:         char cmd[64];
60:         snprintf(cmd, sizeof cmd, "-target-attach %d\n", (int)pid);
61:         if (write(to_, cmd, strlen(cmd)) < 0) return false;
62:         return WaitFor("*stopped", 60.0);   // the attach stop == device suspended
63:     }
64: 
65:     bool Detach()
66:     {
67:         if (!attached_) return true;
68:         const char *cmd = "-target-detach\n";
69:         if (write(to_, cmd, strlen(cmd)) < 0) return false;
70:         // gdb answers ^done on success and ^error "The program is not being run."
71:         // when the inferior already exited - both mean we are no longer attached.
72:         double t0 = NowSeconds();
73:         while (NowSeconds() - t0 < 10.0) {
74:             size_t nl;
75:             while ((nl = buf_.find('\n')) != std::string::npos) {
76:                 std::string line = buf_.substr(0, nl);
77:                 buf_.erase(0, nl + 1);
78:                 if (line.rfind("^done", 0) == 0 || line.rfind("^error", 0) == 0) {
79:                     attached_ = false;
80:                     return true;
81:                 }
82:             }
83:             if (!Read(50)) break;
84:         }
85:         return false;
86:     }
87: 
88:     void Kill()
89:     {
90:         if (to_ >= 0) { const char *c = "-gdb-exit\n"; ssize_t w = write(to_, c, strlen(c)); (void)w; }
91:         if (pid_ > 0) {
92:             std::this_thread::sleep_for(std::chrono::milliseconds(200));
93:             kill(pid_, SIGKILL);
94:             waitpid(pid_, nullptr, 0);
95:             pid_ = -1;
96:         }
97:         if (to_ >= 0) close(to_);
98:         if (from_ >= 0) close(from_);
99:         to_ = from_ = -1;
100:     }
101: 
102:     bool IsAlive() { return pid_ > 0 && kill(pid_, 0) == 0; }
103:     bool IsAttached() { return attached_; }
104:     void MarkAttached() { attached_ = true; }
105: 
106: private:
107:     bool Read(int timeout_ms)
108:     {
109:         struct pollfd p;
110:         p.fd = from_; p.events = POLLIN; p.revents = 0;
111:         if (poll(&p, 1, timeout_ms) <= 0) return false;
