35: __global__ void ContinuousResumableKernel(uint64_t *__restrict__ d_data,
36:                                           unsigned long long *__restrict__ d_accum,
37:                                           uint32_t *__restrict__ d_step_counter,
38:                                           uint32_t *__restrict__ d_started,
39:                                           uint32_t total_steps,
40:                                           uint64_t step_ns,
41:                                           int n,
42:                                           int do_atomic_accum)
43: {
44:     int tid = blockIdx.x * blockDim.x + threadIdx.x;
45:     if (tid == 0) {
46:         atomicExch(d_started, 1U);
47:     }
48:     __syncthreads();
49: 
50:     for (uint32_t step = 0; step < total_steps; ++step) {
51:         uint64_t t0 = ReadGlobalTimerNs();
52:         uint64_t sink = step + static_cast<uint64_t>(tid);
53:         while ((ReadGlobalTimerNs() - t0) < step_ns) {
54:             sink = sink * 1664525ULL + 1013904223ULL;
55:         }
56:         for (int idx = tid; idx < n; idx += gridDim.x * blockDim.x) {
57:             d_data[idx] += 1ULL + (sink & 0ULL);
58:             if (do_atomic_accum) {
59:                 atomicAdd(d_accum, 1ULL);
60:             }
61:         }
62:         __syncthreads();
63:         if (blockIdx.x == 0 && threadIdx.x == 0) {
64:             atomicMax(d_step_counter, step + 1U);
65:         }
66:     }
67: }
