58: NV_STATUS
59: gpuValidateRegOps
60: (
61:     OBJGPU *pGpu,
62:     NV2080_CTRL_GPU_REG_OP *pRegOps,
63:     NvU32 regOpCount,
64:     NvBool bNonTransactional,
