72:     for (i = 0; i < regOpCount; i++)
73:     {
74:         regStatus = NV2080_CTRL_GPU_REG_OP_STATUS_SUCCESS;
75: 
76:         if (isClientGspPlugin)
77:         {
78:             return NV_ERR_INVALID_ARGUMENT;
79:         }
80:         else
81:         {
82:             NV_STATUS status;
83: 
84:             status = gpuValidateRegOffset(pGpu, pRegOps[i].regOffset, bSkipPermissionValidation);
85:             if (status != NV_OK)
86:             {
87:                 regStatus = NV2080_CTRL_GPU_REG_OP_STATUS_INVALID_OFFSET;
88:             }
89:         }
90:         if (regStatus != NV2080_CTRL_GPU_REG_OP_STATUS_SUCCESS)
91:         {
92:             pRegOps[i].regStatus |= regStatus;
93: 
94:             if (!bNonTransactional)
95:             {
96:                 return NV_ERR_INVALID_ARGUMENT;
97:             }
98:         }
99:     }
100: 
101:     return NV_OK;
102: }
