105: NV_STATUS
106: gpuSetUserRegisterAccessPermissionsInBulk_IMPL(OBJGPU *pGpu, const NvU32 *pOffsetsSizesArr,
107:                                                NvU32 arrSizeBytes, NvBool bAllow)
108: {
