1: // selftrap.cu - drive the live trap handler from inside a running kernel.
2: //
3: // The host-side RM trigger (cuXtraTriggerTrap -> GlobalRegsWrite32 0x419e84
4: // bit31) demonstrably does not deliver a trap to running warps on sm120+595
5: // (freeze.cu: the victim kept counting at 37 M iter/s with the CILP command word
6: // armed at 2).  What *does* enter the handler is a real trap instruction, so
7: // this probe lets the victim trap itself while the command word is armed:
8: //
9: //   block 0 (victim)    : publish counter; at --arm-at iterations write
10: //                         [preempt_buf+4] = cmd, fence, publish, execute
11: //                         brkpt/trap, then publish "returned" and keep spinning
12: //   block 1 (controller): after --clear-ms, write [preempt_buf+4] = 0 and publish
13: //   other blocks        : plain spin (controls)
14: //
15: // Expected if the decoded mechanism is right: with cmd=2 the victim's reason
16: // mask becomes PREEMPT_SAVE|PAUSE_QUIET, the handler loops on it, so block 0's
17: // counter stalls until block 1 clears the word.
18: //
19: // Build: ../build.sh selftrap    Run:
20: //   CUXTRA_CUDA_LIB=/usr/lib/x86_64-linux-gnu/libcuda.so.1 \
21: //   ./selftrap [--cmd 2] [--inst brkpt|trap] [--arm-at 20000000] [--clear-ms 3000]
22: 
23: #include <cstdio>
24: #include <cstdlib>
25: #include <cstring>
26: #include <cstdint>
27: #include <string>
28: #include <atomic>
29: #include <thread>
30: #include <chrono>
31: #include <unistd.h>
32: #include <dlfcn.h>
33: #include <cuda_runtime.h>
34: #include "arena.h"
35: 
36: #define RT_CHECK(x) do { cudaError_t _e = (x); if (_e != cudaSuccess) { \
37:     fprintf(stderr, "[FATAL] %s -> %s @%d\n", #x, cudaGetErrorName(_e), __LINE__); exit(1);} } while (0)
38: 
39: // hc layout: [0..7] per-block counters, [10] armed iteration, [11] returned-from-trap,
40: // [12] controller cleared, [13] trap instruction executed count
41: __global__ void victim_kernel(volatile unsigned long long *hc, volatile unsigned int *cmd,
42:                               unsigned long long cycles, unsigned long long arm_at,
43:                               unsigned int cmd_val, unsigned long long clear_cycles,
44:                               int use_trap_inst)
45: {
46:     unsigned bid = blockIdx.x;
47:     unsigned long long start = clock64(), i = 0;
48: 
49:     if (bid == 1) { // controller: clear the command word after a delay
50:         unsigned long long t0 = clock64();
51:         while (clock64() - t0 < clear_cycles) { i++; if ((i & 0xff) == 0) hc[bid] = i; }
52:         *cmd = 0u;
53:         __threadfence_system();
54:         hc[12] = i;
55:         while (clock64() - start < cycles) { i++; if ((i & 0xff) == 0) hc[bid] = i; }
56:         hc[bid] = i | (1ULL << 62);
57:         return;
58:     }
59: 
60:     while (clock64() - start < cycles) {
61:         i++;
62:         if ((i & 0xff) == 0) hc[bid] = i;
63:         if (bid == 0 && i >= arm_at) {
64:             *cmd = cmd_val;
65:             __threadfence_system();
66:             hc[10] = i;
67:             hc[13] += 1;
68:             if (use_trap_inst) asm volatile("trap;");
69:             else               asm volatile("brkpt;");
70:             hc[11] = i;   // only reached if the handler returned to us
71:             arm_at = (unsigned long long)-1; // trap once
72:         }
73:     }
74:     hc[bid] = i | (1ULL << 63);
75: }
76: 
77: static double now_s()
78: {
79:     static auto t0 = std::chrono::steady_clock::now();
80:     return std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
81: }
