96:         else if (a == "--cmd") cmd_val = (unsigned)strtoul(next().c_str(), nullptr, 0);
97:         else if (a == "--arm-at") arm_at = strtoull(next().c_str(), nullptr, 0);
98:         else if (a == "--inst") inst = next();
99:     }
100:     int use_trap = inst == "trap" ? 1 : 0;
101: 
102:     RT_CHECK(cudaFree(0));
103:     CUcontext ctx = nullptr;
