125: 
126:     printf("[setup] blocks=%ld spin=%ldms clear=%ldms cmd=%u arm_at=%llu inst=%s preempt_buf=%#llx\n",
127:            blocks, spin_ms, clear_ms, cmd_val, arm_at, inst.c_str(),
128:            (unsigned long long)I.preempt_buf);
129: 
130:     std::atomic<bool> done{false};
131:     std::thread wd([&]() {
132:         for (int i = 0; i < 120 && !done.load(); i++) std::this_thread::sleep_for(std::chrono::milliseconds(500));
133:         if (done.load()) return;
134:         printf("[WATCHDOG] 60 s timeout: blk0=%llu armed=%llu returned=%llu cleared=%llu\n",
135:                hc[0] & ~(3ULL << 62), hc[10], hc[11], hc[12]);
136:         _exit(77);
