138:     wd.detach();
139: 
140:     // warmup so the module is resident (lazy loading would serialize the launch)
141:     victim_kernel<<<2, 32, 0, vs>>>(hc_dev, (volatile unsigned int *)(uintptr_t)(I.preempt_buf + 4),
142:                                     1000, (unsigned long long)-1, 0, 1000, use_trap);
143:     RT_CHECK(cudaStreamSynchronize(vs));
144:     memset(hp, 0, 256);
145: 
146:     printf("\n--- launch ---\n");
147:     double t0 = now_s();
148:     victim_kernel<<<(int)blocks, 32, 0, vs>>>(hc_dev, (volatile unsigned int *)(uintptr_t)(I.preempt_buf + 4),
149:                                               cycles, arm_at, cmd_val, clear_cycles, use_trap);
150:     RT_CHECK(cudaGetLastError());
151: 
152:     unsigned long long last = 0, frozen_at = 0, resumed_at = 0;
153:     int stall = 0;
154:     for (int k = 0; k < 200; k++) {
155:         std::this_thread::sleep_for(std::chrono::milliseconds(100));
156:         unsigned long long v = hc[0] & ~(3ULL << 62);
157:         bool completed = (hc[0] >> 63) & 1;
158:         if (k % 5 == 0 || hc[10] || hc[11] || hc[12])
159:             printf("[t=%6.2f] blk0=%-12llu blk1=%-12llu armed=%-10llu returned=%-10llu cleared=%-10llu traps=%llu%s\n",
160:                    now_s() - t0, v, hc[1] & ~(3ULL << 62), hc[10], hc[11], hc[12], hc[13],
161:                    completed ? "  (COMPLETED)" : "");
162:         if (hc[10] && !hc[11]) {           // armed and not returned yet
163:             if (v == last) { stall++; if (stall == 3 && !frozen_at) frozen_at = now_s() - t0; }
164:             else stall = 0;
165:         }
166:         if (frozen_at && v > last && !resumed_at) resumed_at = now_s() - t0;
167:         last = v;
168:         if (completed) break;
169:     }
170: 
171:     printf("\n--- sync ---\n");
172:     double tw = now_s();
173:     cudaError_t se = cudaStreamSynchronize(vs);
174:     printf("[t=%6.2f] sync=%s after %.3f s\n", now_s() - t0, cudaGetErrorName(se), now_s() - tw);
175:     printf("[final] blk0=%llu armed=%llu returned=%llu cleared=%llu traps=%llu\n",
176:            hc[0], hc[10], hc[11], hc[12], hc[13]);
177:     done = true;
178: 
179:     printf("\n================ VERDICT ================\n");
180:     printf("  trap instruction executed : %s (traps=%llu)\n", hc[13] ? "YES" : "no", hc[13]);
181:     printf("  handler returned to kernel: %s\n", hc[11] ? "YES" : "NO");
182:     printf("  victim frozen in handler  : %s%s\n", frozen_at ? "YES" : "no",
183:            frozen_at ? (resumed_at ? " and RESUMED" : " and never resumed") : "");
184:     if (frozen_at) printf("  frozen at t=%.2f s, resumed at t=%.2f s (clear at blk1 mark=%llu)\n",
185:                           frozen_at, resumed_at, hc[12]);
186:     printf("  stream sync               : %s\n", cudaGetErrorName(se));
