81: (
82:     KernelSMDebuggerSession *pKernelSMDebuggerSession,
83:     NV83DE_CTRL_DEBUG_ACCESS_SURFACE_PARAMETERS *pParams,
84:     NvBool bWrite
85: )
86: {
87:     OBJGPU *pGpu = GPU_RES_GET_GPU(pKernelSMDebuggerSession);
88:     MemoryManager *pMemoryManager = GPU_GET_MEMORY_MANAGER(pGpu);
89:     RsClient *pClient = RES_GET_CLIENT(pKernelSMDebuggerSession);
90:     NvU32 count = pParams->count;
91:     NvU32 i;
92:     NV_STATUS status = NV_OK;
93:     KernelChannel *pKernelChannel;
94: 
95:     NV_ASSERT_OR_RETURN(rmapiLockIsOwner() && rmGpuLockIsOwner(), NV_ERR_INVALID_LOCK_STATE);
96: 
97:     if (count > MAX_ACCESS_OPS)
98:         return NV_ERR_INVALID_ARGUMENT;
99: 
100:     NV_CHECK_OK_OR_RETURN(LEVEL_ERROR,
101:         CliGetKernelChannel(pClient, pKernelSMDebuggerSession->hChannel, &pKernelChannel));
102: 
103:     for (i = 0; i < count; i++)
104:     {
105:         CLI_DMA_MAPPING_INFO *pDmaMappingInfo;
106:         NvU64 virtAddr = pParams->opsBuffer[i].gpuVA;
107:         NvP64 bufPtr = pParams->opsBuffer[i].pCpuVA;
108:         NvU64 bufSize = pParams->opsBuffer[i].size;
109: 
110:         NV_CHECK_OR_RETURN(LEVEL_ERROR, bufSize != 0, NV_ERR_INVALID_ARGUMENT);
111: 
112:         while (bufSize != 0)
113:         {
114:             NvU64 curSize = bufSize;
115: 
116:             // The memory has to be mapped in a single in a single call by the same client
117:             NV_CHECK_OR_RETURN(LEVEL_ERROR,
118:                 CliGetDmaMappingInfo(pClient, RES_GET_PARENT_HANDLE(pKernelSMDebuggerSession),  pKernelChannel->hVASpace,
119:                                      virtAddr, gpumgrGetDeviceGpuMask(pGpu->deviceInstance), &pDmaMappingInfo),
120:                 NV_ERR_INVALID_ARGUMENT);
121: 
122:             NvU64 offsetInMapping = virtAddr - pDmaMappingInfo->DmaOffset;
123:             // Validate offset is within mapping bounds to prevent integer underflow
124:             NV_CHECK_OR_RETURN(LEVEL_ERROR,
125:                 offsetInMapping < pDmaMappingInfo->pMemDesc->Size,
126:                 NV_ERR_INVALID_OFFSET);
127:             curSize = NV_MIN(curSize, pDmaMappingInfo->pMemDesc->Size - offsetInMapping);
128: 
129:             TRANSFER_SURFACE surf = { .pMemDesc = pDmaMappingInfo->pMemDesc, .offset = offsetInMapping };
130:             NvU8 *pKernBuffer = portMemAllocNonPaged(curSize);
131:             NV_CHECK_OR_RETURN(LEVEL_ERROR, pKernBuffer != NULL, NV_ERR_INSUFFICIENT_RESOURCES);
132: 
133:             // Force BAR instead of GSP-DMA copy in CC case
134:             NvU32 transferFlags = TRANSFER_FLAGS_PREFER_PROCESSOR;
135:             if (!memmgrIsKind_HAL(pMemoryManager, FB_IS_KIND_SWIZZLED, memdescGetPteKind(pDmaMappingInfo->pMemDesc)) &&
136:                 !IS_SIMULATION(pGpu))
137:             {
138:                 //
139:                 // CeUtils uses a compressed GMK mapping of the entire FB
140:                 // It won't respect PTE kind swizzling
141:                 // Don't set the flag on simulation, as it forces BAR0 path
142:                 //
143:                 if (gpuIsCCFeatureEnabled(pGpu))
144:                 {
145:                     transferFlags = TRANSFER_FLAGS_NONE;
146:                 }
147:                 else
148:                 {
149:                     transferFlags = TRANSFER_FLAGS_PREFER_CE;
150:                 }
151:             }
152: 
153:             if (bWrite)
154:             {
155:                 NV_ASSERT_OK_OR_CAPTURE_FIRST_ERROR(status,
156:                     portMemExCopyFromUser(bufPtr, pKernBuffer, curSize));
157: 
158:                 // Write out the buffer to memory
159:                 if (status == NV_OK)
160:                 {
161:                     NV_ASSERT_OK_OR_CAPTURE_FIRST_ERROR(status,
162:                         memmgrMemWrite(pMemoryManager, &surf, pKernBuffer, curSize, transferFlags));
163:                 }
164:             }
165:             else
166:             {
167:                 // Read from memory
168:                 NV_ASSERT_OK_OR_CAPTURE_FIRST_ERROR(status,
169:                     memmgrMemRead(pMemoryManager, &surf, pKernBuffer, curSize, transferFlags));
170: 
171:                 if (status == NV_OK)
172:                 {
173:                     NV_ASSERT_OK_OR_CAPTURE_FIRST_ERROR(status,
174:                         portMemExCopyToUser(pKernBuffer, bufPtr, curSize));
175:                 }
176:             }
177: 
178:             portMemFree(pKernBuffer);
179: 
180:             if (status != NV_OK)
181:                 return status;
182: 
183:             bufPtr = NvP64_PLUS_OFFSET(bufPtr, curSize);
184:             bufSize -= curSize;
185:             virtAddr += curSize;
186:         }
187:     }
188: 
189:     return NV_OK;
190: }
