273:         // On GPUs with write-back caches, FB_CACHE_INVALIDATE is reduced
274:         // to FB_CACHE_EVICT, which first writes back dirty lines and then
275:         // invalidates clean ones, exactly what we want. On write-through
276:         // caches, it will invalidate clean lines as expected.
277:         //
278:         NV_CHECK_OK_OR_RETURN(LEVEL_ERROR,
279:             kmemsysCacheOp_HAL(pTempGpu, GPU_GET_KERNEL_MEMORY_SYSTEM(pTempGpu), pMemDesc,
280:                                FB_CACHE_SYSTEM_MEMORY, FB_CACHE_INVALIDATE));
281:     }
282: 
283:     return rmStatus;
284: }
