316: static NV_STATUS
317: _nv83deMapMemoryIntoGrdbgClient
318: (
319:     OBJGPU *pTargetGpu,
320:     KernelSMDebuggerSession *pKernelSMDebuggerSession,
321:     NvHandle hClient,
322:     NvHandle hMemory,
323:     NvU64 offset,
324:     NvU32 length,
325:     NvP64 *ppCpuVirtAddr,
326:     NvU32 flags
327: )
328: {
329:     NV_STATUS rmStatus = NV_OK;
330:     void *pCpuVirtAddr = NULL;
331:     RM_API *pRmApi = rmapiGetInterface(RMAPI_GPU_LOCK_INTERNAL);
332: 
333:     //
334:     // We use our own internal client, dup the memory object into our client
335:     // and then call RmMapMemory on it, so that the memory is never mapped
336:     // into the client's address space.
337:     // hInternalMemMappping must be freed after use, since we don't have space to
338:     // store multiple memory handles.
339:     //
340:     NV_ASSERT_OR_RETURN(pKernelSMDebuggerSession->hInternalMemMapping == NV01_NULL_OBJECT,
341:                         NV_ERR_INVALID_STATE);
342: 
343:     rmStatus = pRmApi->DupObject(pRmApi,
344:                                  pKernelSMDebuggerSession->hInternalClient,
345:                                  pKernelSMDebuggerSession->hInternalDevice,
346:                                  &pKernelSMDebuggerSession->hInternalMemMapping,
347:                                  hClient,
348:                                  hMemory,
349:                                  0);
350:     if (rmStatus != NV_OK)
351:     {
352:         NV_PRINTF(LEVEL_WARNING,
353:                   "Unable to dup source memory (0x%x,0x%x) under device (status = 0x%x). Attempting subdevice dup.\n",
354:                   hClient, hMemory, rmStatus);
355: 
356:         rmStatus = pRmApi->DupObject(pRmApi,
357:                                      pKernelSMDebuggerSession->hInternalClient,
358:                                      pKernelSMDebuggerSession->hInternalSubdevice,
359:                                      &pKernelSMDebuggerSession->hInternalMemMapping,
360:                                      hClient,
361:                                      hMemory,
362:                                      0);
363: 
364:         if (rmStatus != NV_OK)
365:         {
366:             NV_PRINTF(LEVEL_WARNING,
367:                       "Unable to dup source memory (0x%x,0x%x) under subdevice (status = 0x%x). Aborting.\n",
368:                       hClient, hMemory, rmStatus);
369:             return rmStatus;
370:         }
371:     }
372: 
373:     // Map memory
374:     rmStatus = pRmApi->MapToCpu(pRmApi,
375:                                 pKernelSMDebuggerSession->hInternalClient,
376:                                 pKernelSMDebuggerSession->hInternalSubdevice,
377:                                 pKernelSMDebuggerSession->hInternalMemMapping,
378:                                 offset,
379:                                 length,
380:                                 &pCpuVirtAddr,
381:                                 flags);
382:     if (NV_OK != rmStatus)
383:     {
384:         NV_PRINTF(LEVEL_WARNING, "RmMapMemory failed 0x%x\n", rmStatus);
385: 
386:         // Free the memory handle
387:         pRmApi->Free(pRmApi,
388:                      pKernelSMDebuggerSession->hInternalClient,
389:                      pKernelSMDebuggerSession->hInternalMemMapping);
390:         pKernelSMDebuggerSession->hInternalMemMapping = NV01_NULL_OBJECT;
391: 
392:         return rmStatus;
393:     }
394: 
395:     *ppCpuVirtAddr = NV_PTR_TO_NvP64(pCpuVirtAddr);
396: 
397:     return rmStatus;
398: }
