400: static NV_STATUS
401: _nv83deCtrlCmdDebugAccessMemory
402: (
403:     OBJGPU *pTargetGpu,
404:     KernelSMDebuggerSession *pKernelSMDebuggerSession,
405:     NvHandle hClient,
406:     NvHandle hMemory,
407:     NvU64 offset,
408:     NvU32 length,
409:     NvP64 buffer,
410:     GrdbgMemoryAccessType accessType
411: )
412: {
413:     RsResourceRef *pResourceRef;
414:     Memory *pMemory;
415:     MEMORY_DESCRIPTOR *pMemDesc;
416:     NvU64 totalLength;
417:     NV_STATUS rmStatus = NV_OK;
418:     NV_STATUS rmUnmapStatus = NV_OK;
419:     NvU32 flags = 0;
420:     NvBool bGpuCached;
421:     NvBool bCpuMemory;
422: 
423:     //
424:     // SECURITY: Find the hMemory object in the RmCtrl caller's database.
425:     // This ensures the RmCtrl caller has rights to access hMemory.
426:     //
427:     if (serverutilGetResourceRef(hClient, hMemory, &pResourceRef) != NV_OK)
428:         return NV_ERR_INSUFFICIENT_PERMISSIONS;
429: 
430:     pMemory = dynamicCast(pResourceRef->pResource, Memory);
431:     if (pMemory == NULL)
432:     {
433:         rmStatus = NV_ERR_INVALID_ARGUMENT;
434:         NV_PRINTF(LEVEL_WARNING,
435:                   "Invalid handle: hMemory %x is not of type classId(Memory): (GPU 0x%llx, hClient 0x%x, hMemory %x, offset 0x%llx, length 0x%x, flags 0x%x)\n",
436:                   hMemory,
437:                   pTargetGpu->busInfo.gpuPhysAddr,
438:                   hClient,
439:                   hMemory,
440:                   offset,
441:                   length,
442:                   flags);
443:         return rmStatus;
444:     }
445: 
446:     // Get a memdesc for this object to determine its attributes
447:     pMemDesc = pMemory->pMemDesc;
448:     if (pMemDesc == NULL)
449:         return NV_ERR_INVALID_STATE;
450: 
451:     // Sanity-check the requested size
452:     if ((length == 0) || (!portSafeAddU64(offset, length, &totalLength)))
453:         return NV_ERR_INVALID_ARGUMENT;
454:     if (totalLength > pMemDesc->Size)
455:         return NV_ERR_INVALID_ARGUMENT;
456: 
457:     bCpuMemory = (memdescGetAddressSpace(pMemDesc) == ADDR_SYSMEM);
458:     bGpuCached = (memdescGetGpuCacheAttrib(pMemDesc) == NV_MEMORY_CACHED);
459: 
460:     // Ensure previous in-flight accesses are complete
461:     osFlushCpuWriteCombineBuffer();
462: 
463:     if (bCpuMemory && bGpuCached)
464:     {
465:         //
466:         // Flush and invalidate SYSMEM lines from L2s of all GPUs.
467:         // Some GPUs have write-back caches, so this must be done both for
468:         // accessType == READ and accessType == WRITE.
469:         //
470:         NV_ASSERT_OK_OR_RETURN(_nv83deFlushAllGpusL2Cache(pMemDesc));
471:     }
472: 
473:     if (!bCpuMemory && (IS_VIRTUAL_WITHOUT_SRIOV(pTargetGpu) || IS_VIRTUAL_WITH_HEAVY_SRIOV(pTargetGpu)))
474:     {
475:         NvP64 pCpuVirtAddr = NvP64_NULL;
476: 
477:         // Setup mapping flags based on the kind of memory, access type etc.
478:         if (accessType == GRDBG_MEM_ACCESS_TYPE_READ)
479:         {
480:             flags = FLD_SET_DRF(OS33, _FLAGS, _ACCESS, _READ_ONLY, flags);
481:         }
482:         else
483:         {
484:             flags = FLD_SET_DRF(OS33, _FLAGS, _ACCESS, _WRITE_ONLY, flags);
485:         }
486: 
487:         // Map memory into the internal smdbg client
488:         rmStatus = _nv83deMapMemoryIntoGrdbgClient(pTargetGpu,
489:                                                    pKernelSMDebuggerSession,
490:                                                    hClient,
491:                                                    hMemory,
492:                                                    offset,
493:                                                    length,
494:                                                    &pCpuVirtAddr,
495:                                                    flags);
496:         if (NV_OK != rmStatus)
497:         {
498:             NV_PRINTF(LEVEL_WARNING,
499:                       "Failed to map memory into internal smdbg client (GPU 0x%llx, hClient 0x%x, hMemory %x, offset 0x%llx, length 0x%x, flags 0x%x): (rmStatus = %x)\n",
500:                       pTargetGpu->busInfo.gpuPhysAddr,
501:                       hClient,
502:                       hMemory,
503:                       offset,
504:                       length,
505:                       flags,
506:                       rmStatus);
507:             return rmStatus;
508:         }
509: 
510:         // Perform the requested accessType operation
511:         if (accessType == GRDBG_MEM_ACCESS_TYPE_READ)
512:         {
513:             if (!portMemCopy(NvP64_VALUE(buffer), length, NvP64_VALUE(pCpuVirtAddr), length))
514:             {
515:                 rmStatus = NV_ERR_INVALID_ARGUMENT;
516:                 NV_PRINTF(LEVEL_WARNING,
517:                           "portMemCopy failed (from VA 0x" NvP64_fmt " to 0x" NvP64_fmt ", length 0x%x)\n",
518:                           pCpuVirtAddr, buffer, length);
519:                 goto cleanup_mapping;
520:             }
521:             NV_PRINTF(LEVEL_INFO, "Reading %d bytes of memory from 0x%x\n",
522:                       length, hMemory);
523:         }
524:         else
525:         {
526:             if (!portMemCopy(NvP64_VALUE(pCpuVirtAddr), length, NvP64_VALUE(buffer), length))
527:             {
528:                 rmStatus = NV_ERR_INVALID_ARGUMENT;
529:                 NV_PRINTF(LEVEL_WARNING,
530:                           "portMemCopy failed (from VA 0x" NvP64_fmt " to 0x" NvP64_fmt ", length 0x%x)\n",
531:                           buffer, pCpuVirtAddr, length);
532:                 goto cleanup_mapping;
533:             }
534: 
535:             NV_PRINTF(LEVEL_INFO, "Writing %d bytes of memory to 0x%x\n", length,
536:                       hMemory);
537:         }
538: 
539: cleanup_mapping:
540:         // Unmap memory.
541:         rmUnmapStatus = _nv83deUnmapMemoryFromGrdbgClient(pTargetGpu,
542:                                                           pKernelSMDebuggerSession,
543:                                                           pCpuVirtAddr,
544:                                                           flags);
545:     }
546:     else
547:     {
548:         MemoryManager *pMemoryManager = GPU_GET_MEMORY_MANAGER(pTargetGpu);
549:         TRANSFER_SURFACE surf = { .pMemDesc = pMemDesc, .offset = offset };
550:         // Force BAR instead of GSP-DMA copy in CC case
551:         NvU32 transferFlags = TRANSFER_FLAGS_PREFER_PROCESSOR;
552: 
553:         if (gpuIsCCFeatureEnabled(pTargetGpu))
554:         {
555:             if (!gpuIsCCDevToolsModeEnabled(pTargetGpu))
556:             {
557:                 // BAR access would be blocked in CC prod mode
558:                 transferFlags = TRANSFER_FLAGS_NONE;
559:             }
560:         }
561:         else
562:         {
563:             transferFlags |= TRANSFER_FLAGS_PREFER_CE;
564:         }
565: 
566:         if (accessType == GRDBG_MEM_ACCESS_TYPE_READ)
567:         {
568:             NV_CHECK_OK_OR_RETURN(LEVEL_ERROR,
569:                 memmgrMemRead(pMemoryManager, &surf, NvP64_VALUE(buffer), length, transferFlags));
570:         }
571:         else
572:         {
573:             NV_CHECK_OK_OR_RETURN(LEVEL_ERROR,
574:                 memmgrMemWrite(pMemoryManager, &surf, NvP64_VALUE(buffer), length, transferFlags));
575:         }
576:     }
577: 
578:     // Return the first failure
579:     return (rmStatus != NV_OK ? rmStatus: rmUnmapStatus);
580: }
