1: // bar0poke.c - minimal BAR0 read/write probe for the 0x419e84 experiment.
2: //
3: //   sudo ./bin/bar0poke <bdf|resource0-path> <offset> [value] [--write]
4: //
5: // Examples:
6: //   sudo ./bin/bar0poke 0000:01:00.0 0x0            # read PMC_BOOT_0
7: //   sudo ./bin/bar0poke 0000:01:00.0 0x9400         # read PTIMER
8: //   sudo ./bin/bar0poke 0000:01:00.0 0x419e84 0x80000000 --write
9: //
10: // WARNING: writing an unknown PGRAPH/global register can hang the GPU and the
11: // display.  Use a headless/rented GPU or a machine you can reboot.  This
12: // bypasses the NVIDIA driver and GSP-RM; it is a hardware-level experiment,
13: // not a supported path.
14: 
15: #include <stdio.h>
16: #include <stdlib.h>
17: #include <stdint.h>
18: #include <string.h>
19: #include <errno.h>
20: #include <fcntl.h>
21: #include <unistd.h>
22: #include <sys/mman.h>
23: #include <sys/stat.h>
24: 
25: int main(int argc, char **argv)
26: {
27:     if (argc < 3) {
28:         fprintf(stderr, "usage: %s <bdf|resource0-path> <offset> [value] [--write]\n", argv[0]);
29:         return 2;
30:     }
31:     const char *dev = argv[1];
32:     char path[512];
33:     if (dev[0] == '/') snprintf(path, sizeof path, "%s", dev);
34:     else snprintf(path, sizeof path, "/sys/bus/pci/devices/%s/resource0", dev);
35:     unsigned long long off = strtoull(argv[2], NULL, 0);
36:     uint32_t value = argc > 3 ? (uint32_t)strtoul(argv[3], NULL, 0) : 0;
37:     int do_write = 0;
38:     for (int i = 1; i < argc; i++) if (!strcmp(argv[i], "--write")) do_write = 1;
39: 
40:     int fd = open(path, (do_write ? O_RDWR : O_RDONLY) | O_SYNC);
41:     if (fd < 0 && !do_write) fd = open(path, O_RDONLY);
42:     if (fd < 0) {
43:         fprintf(stderr, "[bar0] open %s: %s\n", path, strerror(errno));
44:         return 1;
45:     }
46:     struct stat st;
47:     if (fstat(fd, &st) != 0 || st.st_size <= 0) {
48:         fprintf(stderr, "[bar0] fstat %s: %s size=%lld\n", path, strerror(errno),
49:                 (long long)st.st_size);
50:         close(fd);
51:         return 1;
52:     }
53:     if (off + 4 > (unsigned long long)st.st_size) {
54:         fprintf(stderr, "[bar0] offset %#llx outside BAR size %#llx\n", off,
55:                 (unsigned long long)st.st_size);
56:         close(fd);
57:         return 1;
58:     }
59:     int prot = do_write ? (PROT_READ | PROT_WRITE) : PROT_READ;
60:     void *map = mmap(NULL, (size_t)st.st_size, prot, MAP_SHARED, fd, 0);
61:     if (map == MAP_FAILED) {
62:         fprintf(stderr, "[bar0] mmap %s: %s\n", path, strerror(errno));
63:         close(fd);
64:         return 1;
65:     }
66:     volatile uint32_t *reg = (volatile uint32_t *)map;
67:     uint32_t before = reg[off / 4];
68:     printf("[bar0] %s off=%#llx size=%#llx before=%#010x\n", path, off,
69:            (unsigned long long)st.st_size, before);
70:     if (do_write) {
71:         printf("[bar0] WRITE %#010x -> %#llx (bypassing nvidia.ko/GSP)\n", value, off);
72:         reg[off / 4] = value;
73:         __sync_synchronize();
74:         uint32_t after = reg[off / 4];
75:         printf("[bar0] readback=%#010x\n", after);
76:     }
77:     munmap(map, (size_t)st.st_size);
78:     close(fd);
79:     return 0;
80: }

