1: // Experiment: which trap reason does an MMIO SM STOP_TRIGGER produce, and how
2: // fast do warps enter the trap handler?
3: #include <cuda.h>
4: #include <cuxtra/cuxtra.h>
5: #include "bar0.h"
6: #include "livepatch.h"
7: #include <unistd.h>
8: #include <ctime>
9: #define NB 30
10: __device__ unsigned smid() { unsigned r; asm volatile("mov.u32 %0, %%smid;" : "=r"(r)); return r; }
11: __global__ void work(volatile unsigned long long *ctr, volatile unsigned *sm, long long cycles) {
12:     if (threadIdx.x == 0) sm[blockIdx.x] = smid();
13:     long long t0 = clock64();
14:     while (clock64() - t0 < cycles) if (threadIdx.x == 0) ctr[blockIdx.x] += 1;
15: }
16: __global__ void nop_k() {}
17: static uint64_t ptimer() {
18:     uint32_t hi, lo, hi2;
19:     do { hi = rd32(0x9410); lo = rd32(0x9400); hi2 = rd32(0x9410); } while (hi != hi2);
20:     return ((uint64_t)hi << 32) | lo;
21: }
22: struct Rec { unsigned long long t; unsigned reason, pad; };
23: int main(int argc, char **argv) {
24:     const char *mode = argc > 1 ? argv[1] : "unicast";
25:     if (bar0_open()) return 1;
26:     cudaFree(0); nop_k<<<1, 1>>>(); cudaDeviceSynchronize();
27:     LivePatch P; if (!P.probe()) return 1;
28:     Rec *rec; cudaHostAlloc(&rec, 256 * sizeof(Rec), cudaHostAllocMapped); memset(rec, 0, 256 * sizeof(Rec));
29:     uint64_t rva = (uint64_t)(uintptr_t)rec;
30:     using namespace s120;
31:     std::vector<I> cave = {
32:         mov_imm(3, 0),                        // displaced: MOV R3, RZ (imm 0)
33:         s2r(4, 0x43, 0),                       // S2R R4, SR_VIRTUALSMID
34:         mov_imm(8, (uint32_t)rva), mov_imm(9, (uint32_t)(rva >> 32)),
35:         cs2r_globaltimer(6),
36:         imad_wide_u32_imm(8, 4, sizeof(Rec), 8),
37:         st_e(8, 0, 6, true), st_e(8, 8, 2),
38:         iadd_imm(12, 12, 0x10), ret_r12(),
39:     };
40:     disasm(cave, "/tmp/claude-1000/cave.bin");
41:     if (!P.install(cave)) return 1;
42:     unsigned long long *h; unsigned *hs; cudaHostAlloc(&h, NB * 8, cudaHostAllocMapped); cudaHostAlloc(&hs, NB * 4, cudaHostAllocMapped);
43:     int clk; cudaDeviceGetAttribute(&clk, cudaDevAttrClockRate, 0);
44:     work<<<NB, 128>>>(h, hs, (long long)(1.5 * clk * 1000.0));
45:     usleep(300000);
46:     printf("ptimer=%llu (check vs globaltimer)\n", (unsigned long long)ptimer());
47:     uint32_t reg = strcmp(mode, "bcast") ? 0x504704 : 0x419e84;
