#include <cuda.h>
#include <cuxtra/cuxtra.h>
#include "bar0.h"
#include "arena.h"
#include "sass120.h"
#include <unistd.h>
#include <cstdio>
#include <cstring>

#define NB 30

__device__ unsigned get_smid() {
    unsigned r;
    asm volatile("mov.u32 %0, %%smid;" : "=r"(r));
    return r;
}

__device__ unsigned long long get_globaltimer() {
    unsigned long long r;
    asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(r));
    return r;
}

__global__ void active_kernel(volatile unsigned long long *ctr,
                              volatile unsigned *sm,
                              volatile unsigned long long *gpu_now,
                              volatile int *stop_flag) {
    unsigned my_sm = get_smid();
    if (threadIdx.x == 0) sm[blockIdx.x] = my_sm;
    while (!(*stop_flag)) {
        if (threadIdx.x == 0) {
            ctr[blockIdx.x] += 1;
            if (blockIdx.x == 0) *gpu_now = get_globaltimer();
        }
    }
}

__global__ void warmup_k() {}

static uint64_t read_ptimer() {
    uint32_t hi, lo, hi2;
    do {
        hi = rd32(0x9410);
        lo = rd32(0x9400);
        hi2 = rd32(0x9410);
    } while (hi != hi2);
    return ((uint64_t)hi << 32) | lo;
}

struct TrapRecord {
    unsigned long long t_entry;
    unsigned reason;
    unsigned pad;
};

int main(int argc, char **argv) {
    int nop_entry_drain = (argc > 1 && atoi(argv[1]) != 0) ? 1 : 0;
    int pulse_run = (argc > 2 && atoi(argv[2]) != 0) ? 1 : 0;

    if (bar0_open()) return 1;
    cudaFree(0);
    warmup_k<<<1, 1>>>();
    cudaDeviceSynchronize();

    CUcontext ctx = nullptr;
    cuCtxGetCurrent(&ctx);
    sm120arena::Info info = sm120arena::probe(ctx, 0);
    if (!info.ok || !info.handler_is_memobj) {
        printf("Arena info unavailable\n");
        return 1;
    }

    uint64_t ext_va = info.tools_pc + 0xa00;
    uint64_t orig_000[2], orig_390[2];
    memcpy(orig_000, &info.handler[0x000], 16);
    memcpy(orig_390, &info.handler[0x390], 16);

    TrapRecord *rec;
    cudaHostAlloc(&rec, 256 * sizeof(TrapRecord), cudaHostAllocMapped);
    memset(rec, 0, 256 * sizeof(TrapRecord));
    uint64_t rva = (uint64_t)(uintptr_t)rec;

    using namespace s120;
    // Jump to epilogue at +0x0710:
    // At +0x0370, LEPC R12 sets R12 = handler_va + 0x0370.
    // RET.ABS R12 0x20 jumps to R12 + 0x20.
    // So adding 0x380 to R12 makes RET.ABS R12 0x20 land at handler_va + 0x0370 + 0x380 + 0x20 = handler_va + 0x0710.
    std::vector<I> ext_code = {
        mov_imm(3, 0),
        s2r(4, 0x43, 0),                       // S2R R4, SR_VIRTUALSMID
        mov_imm(8, (uint32_t)rva),
        mov_imm(9, (uint32_t)(rva >> 32)),
        cs2r_globaltimer(6),
        imad_wide_u32_imm(8, 4, sizeof(TrapRecord), 8),
        st_e(8, 0, 6, true),
        st_e(8, 8, 2),
        iadd_imm(12, 12, 0x380),
        ret_r12(),
    };

    auto flat_words = flat(ext_code);
    std::vector<uint64_t> ext_backup(flat_words.size());
    cuXtraMemcpyDtoH(ext_backup.data(), ext_va, flat_words.size() * 8, 0);

    uint64_t o0, o1;
    memcpy(&o0, &info.handler[0x380], 8);
    memcpy(&o1, &info.handler[0x388], 8);
    uint64_t enc = (ext_va - 0x100) >> 8, branch_inst[2];
    branch_inst[0] = ((enc & 0xffffffffULL) << 32) | (o0 & 0xffffffffULL);
    branch_inst[1] = (o1 & ~0xffULL) | ((enc >> 32) & 0xffULL);

    cuXtraMemcpyHtoD(ext_va, flat_words.data(), flat_words.size() * 8, 0);
    cuXtraMemcpyHtoD(info.handler_va + 0x390, branch_inst, 16, 0);
    if (nop_entry_drain) {
        I n = nop();
        uint64_t nw[2] = {n.w0, n.w1};
        cuXtraMemcpyHtoD(info.handler_va + 0x000, nw, 16, 0);
    }
    cuXtraInvalInstrCache(ctx);

    unsigned long long *ctr, *gpu_now;
    unsigned *sm;
    int *stop_flag;
    cudaHostAlloc(&ctr, NB * 8, cudaHostAllocMapped);
    cudaHostAlloc(&sm, NB * 4, cudaHostAllocMapped);
    cudaHostAlloc(&gpu_now, 8, cudaHostAllocMapped);
    cudaHostAlloc(&stop_flag, 4, cudaHostAllocMapped);
    memset(ctr, 0, NB * 8);
    *gpu_now = 0;
    *stop_flag = 0;

    active_kernel<<<NB, 128>>>(ctr, sm, gpu_now, stop_flag);
    while (*gpu_now == 0) usleep(100);
    usleep(5000);

    uint64_t pt0 = read_ptimer();
    uint64_t gt0 = *gpu_now;
    printf("Before trigger: ptimer=%llu gpu_globaltimer=%llu diff=%lld ns\n",
           (unsigned long long)pt0, (unsigned long long)gt0, (long long)(pt0 - gt0));
    printf("Pre-trigger SM0 status0=%08x ctl0=%08x\n", rd32(0x504700), rd32(0x504704));

    uint64_t t_trig = *gpu_now;
    wr32(0x504704, 0x80001c01);
    uint32_t st_after_stop = rd32(0x504700);
    uint32_t ctl_after_stop = rd32(0x504704);

    if (pulse_run == 1) {
        wr32(0x504704, 0x00001c01);
    } else if (pulse_run == 2) {
        usleep(10);
        wr32(0x504704, 0x40001c01);
    }

    usleep(5000);
    uint32_t st_final = rd32(0x504700);
    uint32_t ctl_final = rd32(0x504704);
    printf("After trigger (nop_drain=%d pulse_run=%d): st_stop=%08x ctl_stop=%08x -> st_final=%08x ctl_final=%08x\n",
           nop_entry_drain, pulse_run, st_after_stop, ctl_after_stop, st_final, ctl_final);

    for (int i = 0; i < 256; i++) {
        if (rec[i].t_entry) {
            printf("  vsmid %d: reason=%#x delta_from_gt0=%.2f us (t_entry=%llu)\n",
                   i, rec[i].reason, (double)((long long)(rec[i].t_entry - t_trig)) / 1000.0,
                   (unsigned long long)rec[i].t_entry);
        }
    }

    // Ensure SM0 is not left paused
    if (rd32(0x504700) & 0x10) {
        wr32(0x504704, 0x40001c01);
        usleep(1000);
    }
    *stop_flag = 1;
    cudaError_t err = cudaDeviceSynchronize();
    printf("Kernel completion status: %s\n", cudaGetErrorString(err));

    if (nop_entry_drain) {
        cuXtraMemcpyHtoD(info.handler_va + 0x000, orig_000, 16, 0);
    }
    cuXtraMemcpyHtoD(info.handler_va + 0x390, orig_390, 16, 0);
    cuXtraMemcpyHtoD(ext_va, ext_backup.data(), flat_words.size() * 8, 0);
    cuXtraInvalInstrCache(ctx);
    return 0;
}

