    memset(rec, 0, 256 * sizeof(TrapRecord));

    uint64_t pt0 = read_ptimer();
    uint64_t gt0 = *gpu_now;
    wr32(0x504704, 0x80001c01);

    uint32_t st_after_stop = 0;
    uint64_t pt_stop = pt0;
    for (int spin = 0; spin < 200; spin++) {
        st_after_stop = rd32(0x504700);
        if (st_after_stop != 0) {
            pt_stop = read_ptimer();
            break;
        }
    }
    uint32_t ctl_after_stop = rd32(0x504704);
    uint64_t rec0_before_run = rec[0].t_entry;

    if (pulse_run == 1) {
        wr32(0x504704, 0x00001c01);
    } else if (pulse_run == 2) {
        wr32(0x504704, 0x40001c01);
    } else if (pulse_run == 3) {
        wr32(0x504704, 0x00001c01);
        wr32(0x504704, 0x40001c01);
    }

    usleep(200);
    uint32_t st_final = rd32(0x504700);
    uint32_t ctl_final = rd32(0x504704);
    printf("[nop_drain=%d pulse_run=%d] stop_lat=%llu ns st_stop=%08x ctl_stop=%08x rec0_before_run=%llu -> st_final=%08x ctl_final=%08x\n",
           nop_entry_drain, pulse_run, (unsigned long long)(pt_stop - pt0),
           st_after_stop, ctl_after_stop, (unsigned long long)rec0_before_run,
           st_final, ctl_final);

    for (int i = 0; i < 256; i++) {
        if (rec[i].t_entry) {
            printf("  vsmid %d: reason=%#x delta_from_pt0=%.2f us delta_from_gt0=%.2f us\n",
                   i, rec[i].reason,
                   (double)((long long)(rec[i].t_entry - pt0)) / 1000.0,
                   (double)((long long)(rec[i].t_entry - gt0)) / 1000.0);
        }
    }

    if (rd32(0x504700) & 0x10) {
        wr32(0x504704, 0x40001c01);
        usleep(200);
    }
    *stop_flag = 1;
    cudaError_t err = cudaDeviceSynchronize();
    printf("Kernel completion status: %s\n", cudaGetErrorString(err));

    if (nop_entry_drain) {
        cuXtraMemcpyHtoD(info.handler_va + 0x000, orig_000, 16, 0);
    }
    cuXtraMemcpyHtoD(info.handler_va + 0x390, orig_390, 16, 0);
    cuXtraMemcpyHtoD(ext_va, ext_backup.data(), flat_words.size() * 8, 0);
    cuXtraInvalInstrCache(ctx);
    return 0;
}

