#include <cuda.h>
#include <cuxtra/cuxtra.h>
#include "bar0.h"
#include "arena.h"
#include "sass120.h"
#include <unistd.h>
#include <cstdio>
#include <cstring>

__device__ unsigned long long get_globaltimer() {
    unsigned long long r;
    asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(r));
    return r;
}

__global__ void stream_worker(volatile unsigned long long *progress,
                              volatile unsigned long long *t_last,
                              unsigned long long duration_ns) {
    unsigned long long t0 = get_globaltimer();
    unsigned long long local_cnt = 0;
    while (get_globaltimer() - t0 < duration_ns) {
        local_cnt++;
        if ((local_cnt & 0xff) == 0 && threadIdx.x == 0) {
            progress[blockIdx.x] = local_cnt;
            if (blockIdx.x == 0) *t_last = get_globaltimer();
        }
    }
    if (threadIdx.x == 0) {
        progress[blockIdx.x] = local_cnt | (1ULL << 62); // normal completion marker
        if (blockIdx.x == 0) *t_last = get_globaltimer();
    }
}

__global__ void warmup_k() {}

static uint64_t read_ptimer() {
    uint32_t hi, lo, hi2;
    do {
        hi = rd32(0x9410);
        lo = rd32(0x9400);
        hi2 = rd32(0x9410);
    } while (hi != hi2);
    return ((uint64_t)hi << 32) | lo;
}

// Helper instructions for SM120
namespace s120_ext {
using namespace s120;

// LDC Rd, c[0x0][off] with wb=0
inline I ldc_u32(int rd, uint32_t off) {
    uint32_t word_off = off >> 2;
    return {((uint64_t)word_off << 32) | 0xff000000ULL | ((uint64_t)rd << 16) | 0x7b82ULL,
            0x00000800ULL | ctl(15, 0x3f, 0)};
}

// LD.E R0, [R4] with wb=0
inline I ld_e_r0_r4() {
    return {0x0000000004007980ULL, 0x00100900ULL | ctl(15, 0x3f, 0)};
}

// ISETP.NE.AND P0, PT, Ra, RZ, PT
inline I isetp_ne_rz(int ra) {
    return {0x000000ff0000720cULL | ((uint64_t)ra << 24),
            0x03f05270ULL | ctl(15, 0x3f)};
}

// @!P0 BRA +n_instrs (relative to next instruction)
inline I bra_not_p0(int n_instrs) {
    return {((uint64_t)(n_instrs * 4) << 16) | 0x8947ULL,
            0x03800000ULL | ctl(15, 0x3f)};
}
} // namespace s120_ext

int main() {
    if (bar0_open()) return 1;
    cudaFree(0);
    warmup_k<<<1, 1>>>();
    cudaDeviceSynchronize();

    CUcontext ctx = nullptr;
    cuCtxGetCurrent(&ctx);
    sm120arena::Info info = sm120arena::probe(ctx, 0);
    if (!info.ok || !info.handler_is_memobj) {
        printf("Arena info unavailable\n");
        return 1;
    }

    // Extract STL.64 [0xffffa8], R0 from handler + 0x110
    s120::I stl_64_rpc;
    memcpy(&stl_64_rpc.w0, &info.handler[0x110], 8);
    memcpy(&stl_64_rpc.w1, &info.handler[0x118], 8);
    stl_64_rpc.w1 = (stl_64_rpc.w1 & 0x1ffffffffffULL) | s120::ctl(15, 0x3f);

    // Extract LOP3.LUT R2, R2, 0x10, RZ, 0xc0, !PT from handler + 0x220
    uint64_t lop_w0, lop_w1;
    memcpy(&lop_w0, &info.handler[0x220], 8);
    memcpy(&lop_w1, &info.handler[0x228], 8);
    s120::I mask_r2_bit10 = {(lop_w0 & 0xffffffffULL) | (0x10ULL << 32), lop_w1};

    uint64_t ext_va = info.tools_pc + 0xa00;
    uint64_t exit_stub_va = info.tools_pc + 0xb80; // Normal-mode EXIT stub

    using namespace s120;
    using namespace s120_ext;
    // Build selective per-stream trap routine:
    // 0: LDC R8, c[0x0][0x188]          (killable flag)
    // 1: ISETP.NE.AND P0, PT, R8, RZ, PT
    // 2: @!P0 BRA +10 (-> idx 13: done)
    // 3: LDC R4, c[0x0][0x170]          (preempt_buf lo)
    // 4: LDC R5, c[0x0][0x174]          (preempt_buf hi)
    // 5: ISETP.NE.AND P0, PT, R4, RZ, PT
    // 6: @!P0 BRA +6  (-> idx 13: done)
    // 7: LD.E R0, [R4]                  (*preempt_buf = global_exit_flag)
    // 8: ISETP.NE.AND P0, PT, R0, RZ, PT
    // 9: @!P0 BRA +3  (-> idx 13: done)
    // 10: MOV R0, lo32(exit_stub_va)
    // 11: MOV R1, hi32(exit_stub_va)
    // 12: STL.64 [0xffffa8], R0         (redirect TRAP_RETURN_PC to normal-mode EXIT!)
    // 13 (done):
    // 13: MOV R1, 0xffff80              (restore trap handler stack pointer R1)
    // 14: MOV R3, 0                     (displaced instruction at +0x390)
    // 15: LOP3.LUT R2, R2, 0x10, RZ     (clear debugger stop bits, preserve 0x10 context switch)
    // 16: IADD R12, R12, 0x10
    // 17: RET.ABS R12 0x20
    std::vector<I> ext_code = {
        ldc_u32(8, 0x188),
        isetp_ne_rz(8),
        bra_not_p0(10),
        ldc_u32(4, 0x170),
        ldc_u32(5, 0x174),
        isetp_ne_rz(4),
        bra_not_p0(6),
        ld_e_r0_r4(),
        isetp_ne_rz(0),
        bra_not_p0(3),
        mov_imm(0, (uint32_t)exit_stub_va),
        mov_imm(1, (uint32_t)(exit_stub_va >> 32)),
        stl_64_rpc,
        mov_imm(1, 0xffff80),
        mov_imm(3, 0),
        mask_r2_bit10,
        iadd_imm(12, 12, 0x10),
        ret_r12(),
    };

    printf("Disassembling selective per-stream trap routine:\n");
    disasm(ext_code, "/tmp/stream_trap_ext.bin");

    std::vector<I> exit_stub = { exit_(), exit_() };
    auto flat_ext = flat(ext_code);
    auto flat_exit = flat(exit_stub);

    uint64_t orig_390[2];
    memcpy(orig_390, &info.handler[0x390], 16);
    std::vector<uint64_t> ext_backup(flat_ext.size());
    std::vector<uint64_t> exit_backup(flat_exit.size());
    cuXtraMemcpyDtoH(ext_backup.data(), ext_va, flat_ext.size() * 8, 0);
    cuXtraMemcpyDtoH(exit_backup.data(), exit_stub_va, flat_exit.size() * 8, 0);

    uint64_t o0, o1;
    memcpy(&o0, &info.handler[0x380], 8);
    memcpy(&o1, &info.handler[0x388], 8);
    uint64_t enc = (ext_va - 0x100) >> 8, branch_inst[2];
    branch_inst[0] = ((enc & 0xffffffffULL) << 32) | (o0 & 0xffffffffULL);
    branch_inst[1] = (o1 & ~0xffULL) | ((enc >> 32) & 0xffULL);

    cuXtraMemcpyHtoD(exit_stub_va, flat_exit.data(), flat_exit.size() * 8, 0);
    cuXtraMemcpyHtoD(ext_va, flat_ext.data(), flat_ext.size() * 8, 0);
    cuXtraMemcpyHtoD(info.handler_va + 0x390, branch_inst, 16, 0);
    cuXtraInvalInstrCache(ctx);

    // Create TWO streams in the SAME CUDA context!
    CUstream stream_low, stream_high;
    cuStreamCreate(&stream_low, CU_STREAM_NON_BLOCKING);
    cuStreamCreate(&stream_high, CU_STREAM_NON_BLOCKING);

    // Allocate mapped preempt buffers and progress counters
    uint32_t *preempt_buf_low, *preempt_buf_high;
    unsigned long long *prog_low, *prog_high, *t_last_low, *t_last_high;
    cudaHostAlloc(&preempt_buf_low, 64, cudaHostAllocMapped);
    cudaHostAlloc(&preempt_buf_high, 64, cudaHostAllocMapped);
    cudaHostAlloc(&prog_low, 15 * 8, cudaHostAllocMapped);
    cudaHostAlloc(&prog_high, 15 * 8, cudaHostAllocMapped);
    cudaHostAlloc(&t_last_low, 8, cudaHostAllocMapped);
    cudaHostAlloc(&t_last_high, 8, cudaHostAllocMapped);
    memset(preempt_buf_low, 0, 64);
    memset(preempt_buf_high, 0, 64);
    memset(prog_low, 0, 15 * 8);
    memset(prog_high, 0, 15 * 8);
    *t_last_low = 0;
    *t_last_high = 0;

    CUfunction func = nullptr;
    cudaGetFuncBySymbol(&func, (const void *)stream_worker);

    // 1. Launch low-priority kernel on stream_low (configured for 3,000 ms = 3 seconds!)
    struct {
        uint64_t preempt_buf;
        uint64_t guardian;
        int64_t kernel_idx;
        uint32_t killable;
    } __attribute__((packed)) dbg_params;

    dbg_params.preempt_buf = (uint64_t)(uintptr_t)preempt_buf_low;
    dbg_params.guardian = 0;
    dbg_params.kernel_idx = 1;
    dbg_params.killable = 1;
    cuXtraSetDebuggerParams(func, &dbg_params, sizeof(dbg_params));

    unsigned long long dur_low = 3000000000ULL; // 3.0 seconds!
    void *args_low[] = { &prog_low, &t_last_low, &dur_low };
    cuLaunchKernel(func, 15, 1, 1, 128, 1, 1, 0, stream_low, args_low, nullptr);

    // 2. Launch high-priority kernel on stream_high in the SAME context (configured for 150 ms)
    dbg_params.preempt_buf = (uint64_t)(uintptr_t)preempt_buf_high;
    dbg_params.guardian = 0;
    dbg_params.kernel_idx = 2;
    dbg_params.killable = 1;
    cuXtraSetDebuggerParams(func, &dbg_params, sizeof(dbg_params));

    unsigned long long dur_high = 150000000ULL; // 150 ms
    void *args_high[] = { &prog_high, &t_last_high, &dur_high };
    cuLaunchKernel(func, 15, 1, 1, 128, 1, 1, 0, stream_high, args_high, nullptr);

    // Wait until both streams are actively running on the GPU
    while (*t_last_low == 0 || *t_last_high == 0) usleep(10);
    usleep(20000); // 20 ms into execution

    printf("Both streams running in SAME CUcontext! prog_low[0]=%llu prog_high[0]=%llu\n",
           prog_low[0], prog_high[0]);

    // Preempt ONLY stream_low!
    uint64_t t_preempt_start = read_ptimer();
    *preempt_buf_low = 1;
    __sync_synchronize();
    wr32(0x424684, 0x80001c01);
    wr32(0x424684, 0x00001c01);
    uint64_t t_mmio_done = read_ptimer();

    // Synchronize ONLY stream_low to measure total stream preemption latency!
    CUresult res_low = cuStreamSynchronize(stream_low);
    uint64_t t_low_synced = read_ptimer();

    uint64_t gpu_low_stop_ns = (*t_last_low > t_preempt_start) ? (*t_last_low - t_preempt_start) : 0;
    printf("[stream_low preempted!] res_low=%d | MMIO=%0.2f us | GPU last_ts delta=%0.2f us | Host cuStreamSynchronize latency=%0.2f us!\n",
           (int)res_low,
           (t_mmio_done - t_preempt_start) / 1000.0,
           gpu_low_stop_ns / 1000.0,
           (t_low_synced - t_preempt_start) / 1000.0);

    // Check if stream_high is STILL running and finishes normally!
    unsigned long long high_mid = prog_high[0] & ~(1ULL << 62);
    CUresult res_high = cuStreamSynchronize(stream_high);
    unsigned long long high_end = prog_high[0];
    bool high_completed_normally = (high_end & (1ULL << 62)) != 0;
    bool low_aborted_early = (prog_low[0] & (1ULL << 62)) == 0;

    printf("[stream_high isolation] res_high=%d | high_mid=%llu -> high_end=%llu | normal_completion=%d | low_early_exit=%d\n",
           (int)res_high, high_mid, high_end & ~(1ULL << 62),
           (int)high_completed_normally, (int)low_aborted_early);

    // Verify we can immediately relaunch on stream_low!
    *preempt_buf_low = 0;
    unsigned long long dur_relaunch = 10000000ULL; // 10 ms
    void *args_relaunch[] = { &prog_low, &t_last_low, &dur_relaunch };
    dbg_params.preempt_buf = (uint64_t)(uintptr_t)preempt_buf_low;
    cuXtraSetDebuggerParams(func, &dbg_params, sizeof(dbg_params));
    cuLaunchKernel(func, 15, 1, 1, 128, 1, 1, 0, stream_low, args_relaunch, nullptr);
    CUresult res_relaunch = cuStreamSynchronize(stream_low);
    printf("[stream_low relaunch] res=%d | normal_completion=%d\n",
           (int)res_relaunch, (int)((prog_low[0] & (1ULL << 62)) != 0));

    // Restore handler
    cuXtraMemcpyHtoD(info.handler_va + 0x390, orig_390, 16, 0);
    cuXtraMemcpyHtoD(ext_va, ext_backup.data(), flat_ext.size() * 8, 0);
    cuXtraMemcpyHtoD(exit_stub_va, exit_backup.data(), flat_exit.size() * 8, 0);
    cuXtraInvalInstrCache(ctx);
    return 0;
}

