#include <cuda.h>
#include <cuxtra/cuxtra.h>
#include "bar0.h"
#include "arena.h"
#include "sass120.h"
#include <unistd.h>
#include <cstdio>
#include <cstring>

__device__ unsigned long long get_globaltimer() {
    unsigned long long r;
    asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(r));
    return r;
}

__global__ void stream_worker(volatile unsigned long long *progress,
                              volatile unsigned long long *t_last,
                              unsigned long long duration_ns) {
    unsigned long long t0 = get_globaltimer();
    unsigned long long local_cnt = 0;
    while (get_globaltimer() - t0 < duration_ns) {
        local_cnt++;
        if ((local_cnt & 0xff) == 0 && threadIdx.x == 0) {
            progress[blockIdx.x] = local_cnt;
            if (blockIdx.x == 0) *t_last = get_globaltimer();
        }
    }
    if (threadIdx.x == 0) {
        progress[blockIdx.x] = local_cnt | (1ULL << 62);
        if (blockIdx.x == 0) *t_last = get_globaltimer();
    }
}

__global__ void warmup_k() {}

struct InspectRec {
    uint64_t trap_return_pc;
    uint64_t c170_ptr;
    uint32_t c188_flag;
    uint32_t reason;
};

int main() {
    if (bar0_open()) return 1;
    cudaFree(0);
    warmup_k<<<1, 1>>>();
    cudaDeviceSynchronize();

    CUcontext ctx = nullptr;
    cuCtxGetCurrent(&ctx);
    sm120arena::Info info = sm120arena::probe(ctx, 0);
    if (!info.ok || !info.handler_is_memobj) return 1;

    // Extract LDL.64 R4, [0xffffa8] from handler + 0x710
    s120::I ldl_64_rpc;
    memcpy(&ldl_64_rpc.w0, &info.handler[0x710], 8);
    memcpy(&ldl_64_rpc.w1, &info.handler[0x718], 8);

    // Extract LOP3.LUT R2, R2, 0x10, RZ, 0xc0, !PT from handler + 0x220
    uint64_t lop_w0, lop_w1;
    memcpy(&lop_w0, &info.handler[0x220], 8);
    memcpy(&lop_w1, &info.handler[0x228], 8);
    s120::I mask_r2_bit10 = {(lop_w0 & 0xffffffffULL) | (0x10ULL << 32), lop_w1};

    InspectRec *rec;
    cudaHostAlloc(&rec, 256 * sizeof(InspectRec), cudaHostAllocMapped);
    memset(rec, 0, 256 * sizeof(InspectRec));
    uint64_t rva = (uint64_t)(uintptr_t)rec;

    using namespace s120;
    // LDC R6, c[0x0][0x170] and LDC R7, c[0x0][0x174] and LDC R10, c[0x0][0x188]
    I ldc_r6_170 = {0x00005c00ff067b82ULL, 0x000e220000000800ULL};
    I ldc_r7_174 = {0x00005d00ff077b82ULL, 0x000e220000000800ULL};
    I ldc_r10_188 = {0x00006200ff0a7b82ULL, 0x000e220000000800ULL};

    std::vector<I> ext_code = {
        s2r(0, 0x43, 0),                       // S2R R0, SR_VIRTUALSMID
        mov_imm(8, (uint32_t)rva),
        mov_imm(9, (uint32_t)(rva >> 32)),
        imad_wide_u32_imm(8, 0, sizeof(InspectRec), 8),
        ldl_64_rpc,                            // LDL.64 R4, [0xffffa8]
        ldc_r6_170,
        ldc_r7_174,
        ldc_r10_188,
        st_e(8, 0, 4, true),                   // rec[vsmid].trap_return_pc = R4:R5
        st_e(8, 8, 6, true),                   // rec[vsmid].c170_ptr = R6:R7
        st_e(8, 16, 10, false),                // rec[vsmid].c188_flag = R10
        st_e(8, 20, 2, false),                 // rec[vsmid].reason = R2
        mov_imm(3, 0),
        mask_r2_bit10,
        iadd_imm(12, 12, 0x10),
        ret_r12(),
    };

    uint64_t ext_va = info.tools_pc + 0xa00;
    auto flat_ext = flat(ext_code);
    uint64_t orig_390[2];
    memcpy(orig_390, &info.handler[0x390], 16);
    std::vector<uint64_t> ext_backup(flat_ext.size());
    cuXtraMemcpyDtoH(ext_backup.data(), ext_va, flat_ext.size() * 8, 0);

    uint64_t o0, o1;
    memcpy(&o0, &info.handler[0x380], 8);
    memcpy(&o1, &info.handler[0x388], 8);
    uint64_t enc = (ext_va - 0x100) >> 8, branch_inst[2];
    branch_inst[0] = ((enc & 0xffffffffULL) << 32) | (o0 & 0xffffffffULL);
    branch_inst[1] = (o1 & ~0xffULL) | ((enc >> 32) & 0xffULL);

    cuXtraMemcpyHtoD(ext_va, flat_ext.data(), flat_ext.size() * 8, 0);
    cuXtraMemcpyHtoD(info.handler_va + 0x390, branch_inst, 16, 0);
    cuXtraInvalInstrCache(ctx);

    CUstream stream_low;
    cuStreamCreate(&stream_low, CU_STREAM_NON_BLOCKING);
    uint32_t *preempt_buf_low;
    unsigned long long *prog_low, *t_last_low;
    cudaHostAlloc(&preempt_buf_low, 64, cudaHostAllocMapped);
    cudaHostAlloc(&prog_low, 30 * 8, cudaHostAllocMapped);
    cudaHostAlloc(&t_last_low, 8, cudaHostAllocMapped);
    *t_last_low = 0;

    CUfunction func = nullptr;
    cudaGetFuncBySymbol(&func, (const void *)stream_worker);
    CUdeviceptr ep_orig = cuXtraGetEntryPoint(func);

    struct {
        uint64_t preempt_buf;
        uint64_t guardian;
        int64_t kernel_idx;
        uint32_t killable;
    } __attribute__((packed)) dbg_params;
    dbg_params.preempt_buf = (uint64_t)(uintptr_t)preempt_buf_low;
    dbg_params.guardian = ep_orig;
    dbg_params.kernel_idx = 0x1234;
    dbg_params.killable = 1;
    cuXtraSetDebuggerParams(func, &dbg_params, sizeof(dbg_params));

    unsigned long long dur_low = 50000000ULL; // 50 ms
    void *args_low[] = { &prog_low, &t_last_low, &dur_low };
    cuLaunchKernel(func, 30, 1, 1, 128, 1, 1, 0, stream_low, args_low, nullptr);

    while (*t_last_low == 0) usleep(10);
    usleep(10000);
    memset(rec, 0, 256 * sizeof(InspectRec));

    wr32(0x424684, 0x80001c01);
    wr32(0x424684, 0x00001c01);
    usleep(500);

    printf("func entry_point=%#llx expected preempt_buf=%#llx\n",
           (unsigned long long)ep_orig, (unsigned long long)dbg_params.preempt_buf);
    for (int i = 0; i < 6; i++) {
        printf("  vsmid %d: trap_return_pc=%#llx c170_ptr=%#llx c188_flag=%#x reason=%#x\n",
               i, (unsigned long long)rec[i].trap_return_pc,
               (unsigned long long)rec[i].c170_ptr, rec[i].c188_flag, rec[i].reason);
    }

    cuStreamSynchronize(stream_low);
    cuXtraMemcpyHtoD(info.handler_va + 0x390, orig_390, 16, 0);
    cuXtraMemcpyHtoD(ext_va, ext_backup.data(), flat_ext.size() * 8, 0);
    cuXtraInvalInstrCache(ctx);
    return 0;
}

