static uint64_t read_ptimer() {
    uint32_t hi, lo, hi2;
    do {
        hi = rd32(0x9410);
        lo = rd32(0x9400);
        hi2 = rd32(0x9410);
    } while (hi != hi2);
    return ((uint64_t)hi << 32) | lo;
}

