15: InstrumentContext::InstrumentContext(CUcontext ctx): kCtx(ctx)
16: {
17:     // check current context
18:     CUcontext current_ctx;
19:     CUDA_ASSERT(Driver::CtxGetCurrent(&current_ctx));
20:     XASSERT(current_ctx == ctx,
21:             "create InstrumentContext failed: current context (%p) does not match context (%p)",
22:             current_ctx, ctx);
23: 
24:     // create a non-blocking operation stream with highest priority
25:     int lp, hp;
26:     CUDA_ASSERT(Driver::CtxGetStreamPriorityRange(&lp, &hp));
27:     CUDA_ASSERT(Driver::StreamCreateWithPriority(&op_stream_, CU_STREAM_NON_BLOCKING, hp));
28: 
29:     CUdevice dev;
30:     CUDA_ASSERT(Driver::CtxGetDevice(&dev));
31:     guardian_ = Guardian::Instance(dev);
32:     if (getenv("XSCHED_SM120_TRAP_MIN_CTX") != nullptr) {
33:         // Diagnostic: bisect which cuXtra setup turns the sm120 0x83de0317
34:         // from "trap delivered to the handler" into "in-flight work cancelled".
35:         XINFO("InstrumentContext: minimal mode (no instr mem / preempt buffer)");
36:         return;
37:     }
38:     instr_mem_ = std::make_unique<InstrMemAllocator>(kCtx, dev);
39:     preempt_buf_ = std::make_unique<ResizableBuffer>(dev);
40:     // clear the preempt buffer
41:     CUDA_ASSERT(Driver::MemsetD8Async(preempt_buf_->Ptr(), 0, preempt_buf_->Size(), op_stream_));
42:     CUDA_ASSERT(Driver::StreamSynchronize(op_stream_));
43: 
44:     // prepare the resume instructions
45:     size_t resume_size;
46:     const void *resume_host;
47:     guardian_->GetResumeInstructions(&resume_host, &resume_size);
48:     entry_point_resume_ = instr_mem_->Alloc(resume_size);
49:     cuXtraInstrMemcpyHtoD(entry_point_resume_, resume_host, resume_size, op_stream_);
50: }
