52: std::shared_ptr<InstrumentContext> InstrumentContext::Instance(CUcontext ctx)
53: {
54:     static std::mutex ctx_mtx;
55:     static std::map<CUcontext, std::shared_ptr<InstrumentContext>> ctx_map;
56: 
57:     std::lock_guard<std::mutex> lock(ctx_mtx);
58:     auto it = ctx_map.find(ctx);
59:     if (it != ctx_map.end()) return it->second;
60: 
61:     auto instr_ctx = std::make_shared<InstrumentContext>(ctx);
62:     ctx_map[ctx] = instr_ctx;
63:     return instr_ctx;
64: }
