66: CUresult InstrumentContext::Launch(std::shared_ptr<CudaKernelCommand> kernel,
67:                                    CUstream stream, LaunchType type)
68: {
69:     if (getenv("XSCHED_CUDA_LOG_LAUNCH") != nullptr)
70:         XINFO("InstrumentContext::Launch idx=%ld type=%d stream=%p",
71:               (long)kernel->GetIdx(), (int)type, (void *)stream);
72:     char args_buf[28];
73:     uint64_t *preempt_buf = (uint64_t *)(args_buf +  0); // 1st arg: preempt buffer addr
74:     uint64_t *guardian    = (uint64_t *)(args_buf +  8); // 2nd arg: guardian entry point
75:     int64_t  *kernel_idx  = (int64_t  *)(args_buf + 16); // 3rd arg: kernel index
76:     uint32_t *killable    = (uint32_t *)(args_buf + 24); // 4th arg: killable flag
77: 
78:     if (type == kKernelLaunchOriginal) {
79:         size_t block_cnt = kernel->BlockCnt();
80:         size_t buf_size = 2 * sizeof(uint64_t) + 2 * sizeof(uint32_t) * block_cnt;
81:         preempt_buf_->ExpandTo(buf_size, op_stream_);
82: 
83:         // only preempt_buf is useful in this case
84:         memset(args_buf, 0, sizeof(args_buf));
85:         *preempt_buf = preempt_buf_->Ptr(); // use default (empty) preempt buffer
86: 
87:         if (getenv("XSCHED_CUDA_LOG_LAUNCH"))
88:             XINFO("instr launch(orig): idx=%ld locking", (long)kernel->GetIdx());
89:         launch_mtx_.lock();
90:         cuXtraSetDebuggerParams(kernel->kFuncHandle, args_buf, sizeof(args_buf));
91:         CUresult ret = kernel->LaunchWrapper(stream);
92:         if (getenv("XSCHED_CUDA_LOG_LAUNCH"))
93:             XINFO("instr launch(orig): idx=%ld launched ret=%d",
94:                   (long)kernel->GetIdx(), (int)ret);
95:         launch_mtx_.unlock();
96:         return ret;
97:     }
98: 
99:     *preempt_buf = kernel->preempt_buffer;
100:     *guardian    = kernel->entry_point_guardian;
101:     *kernel_idx  = kernel->GetIdx();
102:     *killable    = kernel->killable;
103:     CUdeviceptr entry_point = type == kKernelLaunchResume
104:                             ? entry_point_resume_ // launch to resume
105:                             : kernel->entry_point_guardian;
106:     
107:     if (getenv("XSCHED_CUDA_LOG_LAUNCH"))
108:         XINFO("instr launch: idx=%ld type=%d locking", (long)kernel->GetIdx(), (int)type);
109:     launch_mtx_.lock();
110:     cuXtraSetDebuggerParams(kernel->kFuncHandle, args_buf, sizeof(args_buf));
111:     cuXtraSetEntryPoint(kernel->kFuncHandle, entry_point);
112:     CUresult ret = kernel->LaunchWrapper(stream);
113:     if (getenv("XSCHED_CUDA_LOG_LAUNCH"))
114:         XINFO("instr launch: idx=%ld type=%d launched ret=%d",
115:               (long)kernel->GetIdx(), (int)type, (int)ret);
116:     cuXtraSetEntryPoint(kernel->kFuncHandle, kernel->entry_point_original);
117:     launch_mtx_.unlock();
118: 
119:     return ret;
120: }

