16: // Non-idempotent stateful kernel:
17: // Every thread updates a stateful recurrence and performs global atomicAdds.
18: // If any warp/CTA is aborted, replayed, or has any register clobbered, the
19: // final atomic counter and per-thread state checksums will mismatch!
20: __global__ void non_idempotent_kernel(volatile unsigned long long *progress,
21:                                       volatile unsigned long long *t_last,
22:                                       unsigned long long *atomic_accum,
23:                                       unsigned int *out_checksums,
24:                                       unsigned int total_iters) {
25:     unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
26:     unsigned int state = tid * 0x9e3779b9u + 0x12345678u;
27: 
28:     for (unsigned int it = 1; it <= total_iters; it++) {
29:         // Stateful non-idempotent recurrence using multiple registers & predicates
30:         state = state * 1664525u + 1013904223u + (it ^ tid);
31:         // Intentional small delay loop to make total runtime ~80 ms
32:         unsigned long long t0 = get_globaltimer();
33:         while (get_globaltimer() - t0 < 300ULL) {
34:             state ^= 0x55aa55aau;
35:             state ^= 0x55aa55aau;
36:         }
37:         if (blockIdx.x == 0 && threadIdx.x == 0) *t_last = get_globaltimer();
38:         if ((it & 0xffu) == 0) {
39:             atomicAdd((unsigned long long *)atomic_accum, 1ULL);
40:             if (threadIdx.x == 0) {
41:                 progress[blockIdx.x] = it;
42:             }
43:         }
44:     }
45:     out_checksums[tid] = state;
