92:         if (hClass == CLASS_CHANNEL && cur.hChannel == 0) cur.hChannel = hObj;
93:         if (hClass == CLASS_COMPUTE && cur.hCompute == 0) cur.hCompute = hObj;
94:         if (hClass == CLASS_SMDBGSSN) {
