239: static bool InitWriter()
240: {
241:     if (T.wr_fn != nullptr) return true;
242:     CUresult r;
243:     if ((r = Driver::ModuleLoadData(&T.wr_mod, kWriterPtx)) != CUDA_SUCCESS) {
244:         XWARN("sm120 trap: cave writer module load -> %d", (int)r);
245:         return false;
246:     }
247:     if ((r = Driver::ModuleGetFunction(&T.wr_fn, T.wr_mod, "l3write")) != CUDA_SUCCESS) {
248:         XWARN("sm120 trap: cave writer function -> %d", (int)r);
249:         T.wr_fn = nullptr;
250:         return false;
251:     }
252:     if ((r = Driver::CtxGetStreamPriorityRange(&T.wr_lowpri, &T.wr_highpri)) != CUDA_SUCCESS)
253:         T.wr_highpri = 0;
254:     if ((r = Driver::StreamCreateWithPriority(&T.wr_stream, CU_STREAM_NON_BLOCKING,
255:                                               T.wr_highpri)) != CUDA_SUCCESS) {
256:         XWARN("sm120 trap: cave writer stream -> %d", (int)r);
257:         T.wr_fn = nullptr;
258:         return false;
259:     }
260:     if ((r = Driver::MemAlloc_v2(&T.wr_buf, 0x200)) != CUDA_SUCCESS) {
261:         XWARN("sm120 trap: cave writer buffer -> %d", (int)r);
262:         T.wr_fn = nullptr;
263:         return false;
264:     }
265:     {
266:         void *hp = nullptr;
267:         if (HostAllocPinned(&hp, 0x1000, CU_MEMHOSTALLOC_DEVICEMAP) == CUDA_SUCCESS) {
268:             memset(hp, 0, 0x1000);
269:             T.rec_host = (volatile uint32_t *)hp;
270:             // UVA: the device address of a host allocation is the host VA.
271:             T.rec_dev = (CUdeviceptr)(uintptr_t)hp;
272:             XINFO("sm120 trap: record page host=%p dev=%#llx", hp,
273:                   (unsigned long long)T.rec_dev);
274:         } else {
275:             XWARN("sm120 trap: host record page unavailable");
276:         }
277:     }
278:     r = Driver::MemcpyHtoD_v2_ptds(T.wr_buf, T.ret_stub, sizeof T.ret_stub);
279:     if (r == CUDA_SUCCESS)
280:         r = Driver::MemcpyHtoD_v2_ptds(T.wr_buf + 0x80, T.armed_stub, sizeof T.armed_stub);
281:     if (r != CUDA_SUCCESS) {
282:         XWARN("sm120 trap: cave writer stub copy -> %d", (int)r);
283:         T.wr_fn = nullptr;
284:         return false;
285:     }
286:     if (getenv("XSCHED_SM120_TRAP_REASON_PROBE") != nullptr) {
287:         std::thread([]() {
288:             sleep(4);
289:             Driver::CtxSetCurrent(T.ctx);
290:             uint32_t v[4] = {0, 0, 0, 0};
291:             CUresult rr = Driver::MemcpyDtoHAsync_v2_ptsz(v, T.wr_buf + 0x100,
292:                                                           sizeof v, T.wr_stream);
293:             if (rr == CUDA_SUCCESS) {
294:                 for (int i = 0; i < 500; i++) {
295:                     if (Driver::StreamQuery_ptsz(T.wr_stream) == CUDA_SUCCESS) break;
296:                     usleep(10000);
297:                 }
298:             }
299:             uint64_t ldg[2] = {0, 0};
300:             Driver::MemcpyDtoHAsync_v2_ptsz(ldg, T.wr_buf + 0x40, sizeof ldg, T.wr_stream);
301:             for (int i = 0; i < 200; i++) {
302:                 if (Driver::StreamQuery_ptsz(T.wr_stream) == CUDA_SUCCESS) break;
303:                 usleep(10000);
304:             }
305:             XINFO("sm120 trap: reason probe buf %#x %#x %#x %#x ldg=%#llx (r=%d)",
306:                   v[0], v[1], v[2], v[3], (unsigned long long)ldg[0], (int)rr);
307:         }).detach();
308:     }
309:     return true;
310: }
