331: // Copy a 32-bit value to an arbitrary device VA with the same concurrent
332: // writer kernel used for the cave (src is prepared in w r_buf+0x1c0).
333: [[maybe_unused]] static bool DeviceWrite32(uint64_t dst_va, uint32_t value)
334: {
335:     if (!InitWriter()) return false;
336:     if (Driver::MemcpyHtoDAsync_v2_ptsz(T.wr_buf + 0x1c0, &value, sizeof value,
337:                                         T.wr_stream) != CUDA_SUCCESS)
338:         return false;
339:     uint64_t dst = dst_va, src = T.wr_buf + 0x1c0;
340:     void *args[2] = { &dst, &src };
341:     if (Driver::LaunchKernel_ptsz(T.wr_fn, 1, 1, 1, 1, 1, 1, 0, T.wr_stream,
342:                                   args, nullptr) != CUDA_SUCCESS)
343:         return false;
344:     for (int i = 0; i < 2000; i++) {
345:         CUresult q = Driver::StreamQuery_ptsz(T.wr_stream);
346:         if (q == CUDA_SUCCESS) return true;
347:         if (q != CUDA_ERROR_NOT_READY) { XWARN("sm120 trap: dev write query %d", (int)q); return false; }
348:         usleep(10);
349:     }
350:     XWARN("sm120 trap: dev write timed out");
351:     return false;
352: }
