207: bool ResumableSm120Context::PreemptPulse()
208: {
209:     if (!EnsureHandles(-1)) {
210:         return false;
211:     }
212:     if (!cilp_enabled_) {
213:         InitCilpMode();
214:     }
215: 
216:     // Reduce TSG timeslice to minimum before preemption so runlist yields immediately
217:     NvA06cCtrlTimesliceParams ts{};
218:     ts.timesliceUs = 1;
