293: bool ResumableSm120Context::Pause(uint64_t *latency_us_out)
294: {
295:     std::lock_guard<std::mutex> lock(mtx_);
296:     if (!initialized_) {
297:         EnsureHandles(-1);
298:         InitCilpMode();
299:         initialized_ = true;
300:     }
301:     uint64_t t0 = NowMicros();
302:     bool ok = false;
303:     if (active_backend_ == Sm120ResumableBackend::kDebuggerSuspend) {
304:         ok = PauseViaDebugger();
305:     } else {
306:         ok = PauseViaCilpTsg();
307:     }
308:     uint64_t dt = NowMicros() - t0;
309:     if (latency_us_out) *latency_us_out = dt;
310:     if (ok) {
311:         paused_.store(true, std::memory_order_release);
312:     }
313:     return ok;
314: }
