316: bool ResumableSm120Context::Resume(uint64_t *latency_us_out)
317: {
318:     std::lock_guard<std::mutex> lock(mtx_);
319:     uint64_t t0 = NowMicros();
320:     bool ok = false;
321:     if (active_backend_ == Sm120ResumableBackend::kDebuggerSuspend) {
322:         ok = ResumeViaDebugger();
323:     } else {
324:         ok = ResumeViaCilpTsg();
325:     }
326:     uint64_t dt = NowMicros() - t0;
327:     if (latency_us_out) *latency_us_out = dt;
328:     if (ok) {
