1288: bool TrapSm120Context::RmFastTrapPulse83de()
1289: {
1290:     Sm120RmCtxHandles h{};
1291:     if (!GetRmHandlesByIndex(target_slot_, &h)) {
1292:         GetLatestRmHandles(&h);
1293:     }
1294:     int fd = (h.ctl_fd >= 0) ? h.ctl_fd : H.fd;
1295:     uint32_t hClient = h.hClient ? h.hClient : H.client;
1296:     uint32_t hTsg = h.hTsg ? h.hTsg : H.tsg;
1297:     uint32_t hSession = h.hDebugger ? h.hDebugger : H.session;
1298:     uint32_t hDbgClient = h.hDebuggerClient ? h.hDebuggerClient : (H.dbg_client ? H.dbg_client : hClient);
1299: 
1300:     if (fd < 0 || hClient == 0) return false;
1301:     bool ok = false;
1302:     if (hSession != 0) {
1303:         struct { uint32_t action; uint32_t pad; } mmu_dbg{1u, 0u};
1304:         rm_control(fd, hDbgClient, hSession, 0x83de0329u, &mmu_dbg, sizeof mmu_dbg);
1305: 
1306:         struct { uint32_t waitForEvent; uint32_t status; } susp{0u, 0u};
1307:         int st1 = rm_control(fd, hDbgClient, hSession, 0x83de0317u, &susp, sizeof susp);
1308: 
1309:         uint32_t dummy = 0;
1310:         int st2 = rm_control(fd, hDbgClient, hSession, 0x83de0310u, &dummy, sizeof dummy);
1311:         int st3 = rm_control(fd, hDbgClient, hSession, 0x83de0318u, &dummy, sizeof dummy);
1312:         (void)st3;
1313:         if (st1 == 0 || st2 == 0) ok = true;
1314:     }
1315:     if (hTsg != 0) {
1316:         struct { uint64_t timesliceUs; } ts{1ULL};
1317:         rm_control(fd, hClient, hTsg, 0xa06c0103u, &ts, sizeof ts);
1318:         struct { uint8_t bWait; uint8_t bManualTimeout; uint8_t pad[2]; uint32_t timeoutUs; } pr{1, 1, {0, 0}, 50000};
1319:         int st = rm_control(fd, hClient, hTsg, 0xa06c0105u, &pr, sizeof pr);
1320:         if (st == 0) ok = true;
1321:     }
1322:     return ok;
1323: }
