1325: bool TrapSm120Context::Init(CUcontext ctx, CUstream stream)
1326: {
1327:     ctx_ = ctx;
1328:     if (!T.inited) {
1329:         T.inited = true; T.ctx = ctx; T.stream = stream;
1330:         prctl(PR_SET_PTRACER, PR_SET_PTRACER_ANY, 0, 0, 0);
1331:         ClearDebuggerLaunchBlocking();
1332:         InitCudbg();
1333: 
1334:         const char *name = getenv("XSCHED_SM120_TRAP_SHM");
1335:         const char *agent_cfg = getenv("XSCHED_SM120_TRAP_AGENT");
1336:         if ((name != nullptr && name[0] != '\0') || (agent_cfg != nullptr && agent_cfg[0] != '\0')) {
1337:             snprintf(T.shm_name, sizeof T.shm_name, "%s", name ? name : L3_TRAP_SHM_NAME);
1338:             int fd = shm_open(T.shm_name, O_CREAT | O_RDWR, 0666);
1339:             if (fd >= 0 && ftruncate(fd, sizeof(L3TrapShm)) == 0) {
1340:                 T.shm = (L3TrapShm *)mmap(nullptr, sizeof(L3TrapShm), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
1341:                 close(fd);
1342:                 if (T.shm == MAP_FAILED) T.shm = nullptr;
1343:             } else if (fd >= 0) {
1344:                 close(fd);
1345:             }
1346:             if (T.shm != nullptr) {
1347:                 memset(T.shm, 0, sizeof *T.shm);
1348:                 T.shm->pid = (uint32_t)getpid();
1349:                 if (agent_cfg && *agent_cfg) {
1350:                     pid_t pid = fork();
1351:                     if (pid == 0) {
1352:                         execl(agent_cfg, agent_cfg, T.shm_name, (char *)nullptr);
1353:                         _exit(127);
1354:                     }
1355:                     T.agent_pid = (int)pid;
1356:                 }
1357:                 for (int i = 0; i < 100 && T.shm->agent_ready == 0; i++) usleep(5000);
1358:                 if (H.client && H.device && T.shm->agent_ready) {
1359:                     struct { uint32_t target, rights, type; } p;
1360:                     p = { H.client, 1, 0x0002 };
1361:                     T.shm->policy_status[0] = rm_control(H.fd, H.client, H.client, 0xd04, &p, sizeof p);
1362:                     p = { H.client, 4, 0x40002 };
1363:                     T.shm->policy_status[1] = rm_control(H.fd, H.client, H.client, 0xd04, &p, sizeof p);
1364:                     p = { T.shm->agent_client, 1, 0x40003 };
1365:                     T.shm->policy_status[2] = rm_control(H.fd, H.client, H.client, 0xd04, &p, sizeof p);
1366:                     T.shm->app_client = H.client;
1367:                     T.shm->device = H.device;
1368:                     T.shm->subdev = H.subdev;
1369:                     T.shm->app_session = H.session;
1370:                     T.shm->ncompute = H.ncompute < L3_TRAP_MAX_KGO ? H.ncompute : L3_TRAP_MAX_KGO;
1371:                     for (uint32_t i = 0; i < T.shm->ncompute; i++) T.shm->computes[i] = H.computes[i];
1372:                     __sync_synchronize();
1373:                     T.shm->magic = L3_TRAP_SHM_MAGIC;
1374:                 }
1375:             }
1376:         }
1377:         T.patched = ProbeAndPatch();
1378:         if (T.shm) T.shm->trap_patch_ok = T.patched ? 1 : 0;
1379:     }
1380:     base_va_  = T.live_base;
1381:     live_va_  = T.handler_va;
1382:     cave_va_  = T.cave_va;
1383:     tramp_va_ = T.cave_va ? (T.cave_va + 0x80) : 0;
1384:     patched_  = T.patched;
1385:     ready_    = T.patched;
1386:     return ready_;
