128: void InstrumentContext::Instrument(std::shared_ptr<CudaKernelCommand> kernel)
129: {
130:     CUfunction func = kernel->kFuncHandle;
131: 
132:     {
133:         std::lock_guard<std::mutex> lock(instrument_mtx_);
134:         auto it = kernels_.find(func);
135:         if (it != kernels_.end()) {
136:             // the kernel has been instrumented
137:             kernel->entry_point_original = it->second.entry_point_original;
138:             kernel->entry_point_guardian = it->second.entry_point_guardian;
139:             return;
140:         }
141:     }
142: 
143:     // the kernel has not been instrumented, instrument it
144:     launch_mtx_.lock();
145:     // get the original entry point of the kernel
146:     CUdeviceptr ep_orig = cuXtraGetEntryPoint(func);
147:     launch_mtx_.unlock();
148: 
149:     instrument_mtx_.lock();
150: 
151:     size_t check_size, kernel_size;
152:     const void *check_host, *kernel_host;
153:     guardian_->GetGuardianInstructions(&check_host, &check_size);
154:     cuXtraGetBinary(kCtx, func, &kernel_host, &kernel_size, false);
155: 
156:     // allocate memory for the instrumented kernel, return ptr is entry point
157:     CUdeviceptr ep_inst = instr_mem_->Alloc(kernel_size + check_size);
158:     // the instrumented kernel starts with the guardian instructions
159:     cuXtraInstrMemcpyHtoD(ep_inst, check_host, check_size, op_stream_);
160:     // followed by the original kernel instructions
161:     cuXtraInstrMemcpyHtoD(ep_inst + check_size, kernel_host, kernel_size, op_stream_);
162:     
163:     // the guardian instructions need per-arch register and barrier floors
164:     size_t req_regs = guardian_->RequiredRegs();
165:     size_t reg_cnt = cuXtraGetLocalRegsPerThread(func);
166:     if (reg_cnt < req_regs) cuXtraSetLocalRegsPerThread(func, req_regs);
167: 
168:     // the guardian instructions need at least one barrier
169:     size_t req_barriers = guardian_->RequiredBarriers();
170:     size_t barrier_cnt = cuXtraGetBarrierCnt(func);
171:     if (barrier_cnt < req_barriers) cuXtraSetBarrierCnt(func, req_barriers);
172: 
173:     // flush instruction cache to take effect
174:     cuXtraInvalInstrCache(kCtx);
175:     
176:     // update the instrumented kernel map
177:     kernels_[func] = InstrumentedKernel {
178:         .func = func,
179:         .entry_point_original = ep_orig,
180:         .entry_point_guardian = ep_inst,
181:     };
182: 
183:     instrument_mtx_.unlock();
184: 
185:     kernel->entry_point_original = ep_orig;
186:     kernel->entry_point_guardian = ep_inst;
187: }
