    FG.handler_va = handler_va;
    FG.ext_va = ext_va;
    FG.exit_stub_va = exit_stub_va;
    FG.installed = true;
    return true;
}

bool TrapSm120Context::BindKernelPreemptBuffer(CUfunction func, uint64_t preempt_buf_va,
