bool TrapSm120Context::TriggerFineGrainedTrapPulse()
{
    if (!EnsureBar0Mapped()) return false;
    FG.bar0[0x424684 / 4] = 0x80001c01u;
    (void)FG.bar0[0x424684 / 4];
