    cudaGetFuncBySymbol(&f_k1, (const void *)non_idempotent_k1);
    cudaGetFuncBySymbol(&f_k2, (const void *)non_idempotent_k2);
    cudaGetFuncBySymbol(&f_low, (const void *)worker_low);
