94:     memset(&ti, 0, sizeof ti);
95:     if (((CUresult(*)(CUcontext, void *))tt[20])(ctx, &ti)) { I.note = "slot20 getter failed"; return I; }
96:     if (((CUresult(*)(CUcontext, void *, uint64_t *))mt[24])(ctx, ti.handle, &I.tools_pc) ||
97:         ((CUresult(*)(void *, uint64_t *))mt[25])(ti.handle, &I.tools_size)) {
98:         I.note = "ObjGetPc/ObjGetSize failed";
