102:     if (cuXtraMemcpyDtoH(I.tools.data(), I.tools_pc, I.tools_size, stream) != I.tools_size) {
103:         I.note = "tools image read failed";
104:         return I;
105:     }
106:     I.scratchpad        = pair_at(&I.tools[0x010]);
107:     I.trap_reason_table = pair_at(&I.tools[0x130]);
108:     I.pause_reason_table= pair_at(&I.tools[0x170]);
109:     I.base = I.trap_reason_table - kTrapReasonTableOff;
