113:     unsigned long long off = 0; unsigned long sz = 0;
114:     I.handler_is_memobj = cuxtra::cuda::FindMemObjHandle(ctx, I.handler_va, &o, &off, &sz);
115:     if (read_handler && I.handler_is_memobj) {
116:         I.handler.resize(kTrapHandlerBytes);
