105: // ---------------------------------------------------------------------------
106: __global__ void high_pri_compute_burst_kernel(
107:     float *out_buf,
108:     volatile unsigned long long *t_first_start,
109:     volatile unsigned long long *t_last_end,
110:     unsigned int inner_loops)
111: {
112:     if (threadIdx.x == 0) {
113:         unsigned long long now = get_globaltimer();
114:         atomicMin((unsigned long long *)t_first_start, now);
115:     }
116: 
117:     unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
