145: __global__ void tiled_sgemm_2d_kernel(
146:     const float * __restrict__ A,
147:     const float * __restrict__ B,
148:     float * __restrict__ C,
149:     int N,
150:     int repeat_count)
151: {
152:     __shared__ float As[TILE_DIM][TILE_DIM];
153:     __shared__ float Bs[TILE_DIM][TILE_DIM];
154: 
155:     int bx = blockIdx.x, by = blockIdx.y;
156:     int tx = threadIdx.x, ty = threadIdx.y;
157:     int row = by * TILE_DIM + ty;
158:     int col = bx * TILE_DIM + tx;
159: 
160:     float acc = 0.0f;
161:     for (int rep = 0; rep < repeat_count; rep++) {
162:         for (int t = 0; t < N / TILE_DIM; t++) {
163:             As[ty][tx] = A[row * N + (t * TILE_DIM + tx)];
164:             Bs[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
165:             __syncthreads();
166:             #pragma unroll
167:             for (int k = 0; k < TILE_DIM; k++) {
168:                 acc = __fmaf_rn(As[ty][k], Bs[k][tx], acc);
169:             }
170:             __syncthreads();
171:         }
172:     }
173:     C[row * N + col] = acc;
174: }
