36: // ---------------------------------------------------------------------------
37: // 1. Heavy Full-Chip Non-Idempotent Low-Priority Compute + Memory Kernel
38: //    - No artificial timer throttling! Every thread executes dense FP32 FMA
39: //      chains + global memory updates + non-idempotent LCG state transitions.
40: // ---------------------------------------------------------------------------
41: __global__ void heavy_non_idempotent_low_kernel(
42:     volatile unsigned long long *cta_progress,
43:     volatile unsigned long long *t_last_issue,
44:     unsigned long long *atomic_accum,
45:     unsigned int *out_checksums,
46:     float *scratch_mem,
47:     unsigned int total_iters)
48: {
49:     unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
50:     unsigned int state = tid * 0x9e3779b9u + 0x12345678u;
51:     float a = (float)(tid & 0xffu) * 0.001f + 1.0001f;
52:     float b = 0.9999f;
53:     float c = 0.0001f;
54: 
55:     for (unsigned int it = 1; it <= total_iters; it++) {
56:         // Dense FP32 FMA chain (64 FMAs = 128 FLOPs per inner loop)
57:         #pragma unroll
58:         for (int k = 0; k < 64; k++) {
59:             a = __fmaf_rn(a, b, c);
60:             b = __fmaf_rn(b, a, c);
61:         }
62:         // Non-idempotent integer state recurrence
63:         state = state * 1664525u + 1013904223u + (it ^ __float_as_uint(a));
64: 
65:         if ((it & 0x3fu) == 0) {
66:             scratch_mem[tid] = a + b;
67:             if (threadIdx.x == 0) {
68:                 unsigned long long now = get_globaltimer();
69:                 cta_progress[blockIdx.x] = it;
70:                 if (blockIdx.x == 0) *t_last_issue = now;
71:                 if ((it & 0xffu) == 0) {
72:                     atomicAdd(atomic_accum, (unsigned long long)(blockDim.x >> 5));
73:                 }
74:             }
75:         }
76:     }
77: 
78:     out_checksums[tid] = state;
79:     if (threadIdx.x == 0) {
80:         cta_progress[blockIdx.x] = total_iters | (1ULL << 62);
81:         if (blockIdx.x == 0) *t_last_issue = get_globaltimer();
82:     }
83: }
