85: static uint32_t compute_ref_checksum(unsigned int tid, unsigned int total_iters) {
86:     unsigned int state = tid * 0x9e3779b9u + 0x12345678u;
87:     float a = (float)(tid & 0xffu) * 0.001f + 1.0001f;
88:     float b = 0.9999f;
89:     float c = 0.0001f;
90:     for (unsigned int it = 1; it <= total_iters; it++) {
91:         for (int k = 0; k < 64; k++) {
92:             a = std::fma(a, b, c);
93:             b = std::fma(b, a, c);
94:         }
95:         uint32_t ua;
96:         memcpy(&ua, &a, sizeof(uint32_t));
97:         state = state * 1664525u + 1013904223u + (it ^ ua);
98:     }
99:     return state;
100: }
