102: // ---------------------------------------------------------------------------
103: // 2. High-Priority Compute-Intensive Burst Kernel (All 30 SMs)
104: //    Records exact t_first_start and t_last_end on GPU globaltimer.
105: // ---------------------------------------------------------------------------
106: __global__ void high_pri_compute_burst_kernel(
107:     float *out_buf,
108:     volatile unsigned long long *t_first_start,
109:     volatile unsigned long long *t_last_end,
110:     unsigned int inner_loops)
111: {
112:     if (threadIdx.x == 0) {
113:         unsigned long long now = get_globaltimer();
114:         atomicMin((unsigned long long *)t_first_start, now);
115:     }
116: 
117:     unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
118:     float r0 = (float)(tid & 0xffu) * 0.01f + 1.0f;
119:     float r1 = r0 + 0.1f, r2 = r0 + 0.2f, r3 = r0 + 0.3f;
120:     float m  = 0.99999f,  a  = 0.00001f;
121: 
122:     // 32 FMAs = 64 FLOPs per loop iteration
123:     for (unsigned int i = 0; i < inner_loops; i++) {
124:         #pragma unroll
125:         for (int k = 0; k < 8; k++) {
126:             r0 = __fmaf_rn(r0, m, a);
127:             r1 = __fmaf_rn(r1, m, r0);
128:             r2 = __fmaf_rn(r2, m, r1);
129:             r3 = __fmaf_rn(r3, m, r2);
130:         }
131:     }
132:     out_buf[tid] = r0 + r1 + r2 + r3;
133: 
134:     __syncthreads();
135:     if (threadIdx.x == 0) {
136:         unsigned long long now = get_globaltimer();
137:         atomicMax((unsigned long long *)t_last_end, now);
138:     }
139: }
