50: struct NVOS21 { uint32_t hRoot, hParent, hObject, hClass;
51:                 uint64_t pAllocParms, pRightsRequested;
52:                 uint32_t paramsSize, flags; int32_t status; };
53: struct NVOS54 { uint32_t hClient, hObject, cmd, flags;
54:                 uint64_t params; uint32_t paramsSize; int32_t status; };
55: static_assert(sizeof(NVOS21) == 48 && sizeof(NVOS54) == 32, "RM ABI");
56: 
57: struct NVOS00 { uint32_t hRoot, hObjectParent, hObjectOld; int32_t status; };
58: 
59: static const unsigned long NV_ESC_RM_FREE    = 0xc0104629UL;
60: static const unsigned long NV_ESC_RM_ALLOC   = 0xc030462bUL;
61: static const unsigned long NV_ESC_RM_CONTROL = 0xc020462aUL;
62: static const uint32_t CLASS_ROOT = 0x41, CLASS_DEVICE = 0x80, CLASS_SUBDEV = 0x2080,
63:                       CLASS_TSG = 0xa06c, CLASS_CHANNEL = 0xc96f,
64:                       CLASS_COMPUTE = 0xcec0, CLASS_SMDBGSSN = 0x83de;
