66: namespace {
67: struct Handles {
68:     int fd = -1;
69:     uint32_t client = 0, device = 0, subdev = 0, tsg = 0, channel = 0, session = 0, dbg_client = 0;
70:     uint32_t ncompute = 0, computes[L3_TRAP_MAX_KGO] = {};
71: } H;
72: 
73: constexpr int kMaxCapturedCtx = 16;
74: Sm120RmCtxHandles g_ctx_table[kMaxCapturedCtx] = {};
75: int g_ctx_count = 0;
76: bool g_pin_debugger_handle = true;
77: 
78: int (*real_ioctl)(int, unsigned long, ...) = nullptr;
79: __thread int in_hook = 0;
80: 
81: void RecordToCtxTable(uint32_t hClass, uint32_t hObj, uint32_t hRoot, int fd)
82: {
83:     if (hClass == CLASS_TSG) {
84:         int idx = (g_ctx_count < kMaxCapturedCtx) ? g_ctx_count++ : (kMaxCapturedCtx - 1);
85:         g_ctx_table[idx].ctl_fd     = (H.fd >= 0) ? H.fd : fd;
86:         g_ctx_table[idx].hClient    = H.client ? H.client : hRoot;
87:         g_ctx_table[idx].hDevice    = H.device;
88:         g_ctx_table[idx].hSubDevice = H.subdev;
89:         g_ctx_table[idx].hTsg       = hObj;
90:     } else if (g_ctx_count > 0) {
91:         Sm120RmCtxHandles &cur = g_ctx_table[g_ctx_count - 1];
92:         if (hClass == CLASS_CHANNEL && cur.hChannel == 0) cur.hChannel = hObj;
93:         if (hClass == CLASS_COMPUTE && cur.hCompute == 0) cur.hCompute = hObj;
94:         if (hClass == CLASS_SMDBGSSN) {
95:             cur.hDebugger       = hObj;
96:             cur.hDebuggerClient = hRoot;
97:         }
98:     }
99: }
