139: extern "C" int ioctl(int fd, unsigned long req, ...)
140: {
141:     va_list ap; va_start(ap, req); void *arg = va_arg(ap, void *); va_end(ap);
142:     if (!real_ioctl) real_ioctl = (int (*)(int, unsigned long, ...))dlsym(RTLD_NEXT, "ioctl");
143:     if (!in_hook && arg && (_IOC_NR(req) == 0x29 || req == NV_ESC_RM_FREE) && g_pin_debugger_handle) {
144:         NVOS00 *fr = reinterpret_cast<NVOS00 *>(arg);
145:         if (H.session != 0 && (fr->hObjectOld == H.session || fr->hRoot == H.dbg_client)) {
146:             fr->status = 0;
147:             return 0;
148:         }
149:     }
150:     int r = real_ioctl(fd, req, arg);
151:     if (in_hook || r || !arg || (_IOC_NR(req) != 0x2b && req != NV_ESC_RM_ALLOC)) return r;
152:     in_hook = 1; LearnAlloc(fd, arg); in_hook = 0;
153:     return r;
154: }
