157: static int rm_control(int fd, uint32_t client, uint32_t obj, uint32_t cmd, void *p, uint32_t n)
158: {
159:     NVOS54 c; memset(&c, 0, sizeof c);
160:     c.hClient = client; c.hObject = obj; c.cmd = cmd;
161:     c.params = (uint64_t)(uintptr_t)p; c.paramsSize = n;
162:     if (!real_ioctl) real_ioctl = (int (*)(int, unsigned long, ...))dlsym(RTLD_NEXT, "ioctl");
163:     int r = real_ioctl(fd, NV_ESC_RM_CONTROL, &c);
164:     return r ? (0x1000000 | r) : c.status;
165: }
