205: // A concurrent kernel that copies one of the two stubs into the cave.  Host
206: // copies to instruction memory wait for the app's blocking streams; a kernel
207: // launched on our own non-blocking stream does not.
208: static const char *kWriterPtx =
209:     ".version 8.7\n.target sm_120\n.address_size 64\n"
210:     ".visible .entry l3write(.param .u64 p, .param .u64 src)\n{\n"
211:     "  .reg .u32 %rtid, %r0;\n"
212:     "  .reg .u64 %rd1, %rd2, %rd3, %rd4, %rd5;\n"
213:     "  ld.param.u64 %rd1, [p];\n"
214:     "  ld.param.u64 %rd2, [src];\n"
215:     "  mov.u32 %rtid, %tid.x;\n"
216:     "  mul.wide.u32 %rd3, %rtid, 4;\n"
217:     "  add.s64 %rd4, %rd1, %rd3;\n"
218:     "  add.s64 %rd5, %rd2, %rd3;\n"
219:     "  ld.global.u32 %r0, [%rd5];\n"
220:     "  st.global.u32 [%rd4], %r0;\n"
221:     "  membar.sys;\n"
222:     "  ret;\n}\n";
