224: // cuMemHostAlloc is not part of the generated Driver wrapper table.
225: static CUresult HostAllocPinned(void **p, size_t n, unsigned flags)
226: {
227:     static CUresult (*fn)(void **, size_t, unsigned) = nullptr;
228:     if (fn == nullptr) {
229:         void *h = dlopen("libcuda.so.1", RTLD_NOW | RTLD_NOLOAD);
230:         if (h == nullptr) h = dlopen("libcuda.so", RTLD_NOW | RTLD_NOLOAD);
231:         if (h != nullptr) {
232:             fn = (CUresult (*)(void **, size_t, unsigned))dlsym(h, "cuMemHostAlloc");
233:         }
234:         if (fn == nullptr) return CUDA_ERROR_NOT_FOUND;
235:     }
236:     return fn(p, n, flags);
237: }
