312: static bool LaunchWriter(bool armed)
313: {
314:     if (!InitWriter()) return false;
315:     uint64_t dst = T.cave_va, src = T.wr_buf + (armed ? 0x80 : 0);
316:     void *args[2] = { &dst, &src };
317:     CUresult r = Driver::LaunchKernel_ptsz(T.wr_fn, 1, 1, 1, 32, 1, 1, 0,
318:                                            T.wr_stream, args, nullptr);
319:     if (r != CUDA_SUCCESS) { XWARN("sm120 trap: cave writer launch -> %d", (int)r); return false; }
320:     // wait for the tiny kernel without synchronising the app's streams
321:     CUresult last = CUDA_SUCCESS;
322:     for (int i = 0; i < 2000; i++) {
323:         last = Driver::StreamQuery_ptsz(T.wr_stream);
324:         if (last == CUDA_SUCCESS) return true;
325:         usleep(10);
326:     }
327:     XWARN("sm120 trap: cave writer did not finish (query=%d)", (int)last);
328:     return false;
329: }
