1340:                 T.shm = (L3TrapShm *)mmap(nullptr, sizeof(L3TrapShm), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
1341:                 close(fd);
1342:                 if (T.shm == MAP_FAILED) T.shm = nullptr;
