1422: bool TrapSm120Context::Trigger()
1423: {
1424:     if (!T.patched) return false;
1425:     if (getenv("XSCHED_SM120_TRAP_NO_TRIGGER")) return true;
1426:     if (T.shm == nullptr || T.shm->agent_ready == 0) {
1427:         return RmFastTrapPulse83de();
1428:     }
1429:     bool no_patch = getenv("XSCHED_SM120_TRAP_NO_PATCH") != nullptr;
1430:     bool always = no_patch || getenv("XSCHED_SM120_TRAP_ALWAYS_ARMED") != nullptr;
1431:     bool ret_only = getenv("XSCHED_SM120_TRAP_RETURN_ONLY") != nullptr;
1432:     if (ret_only) always = true;
1433:     if (!always) Arm(true);
1434: 
1435:     bool lazy = getenv("L3AGENT_EAGER") == nullptr;
1436:     if (lazy && T.shm->session != 0) lazy = false;
1437:     if (lazy) {
1438:         uint32_t sg = T.shm->session_req + 1;
1439:         T.shm->session_req = sg;
1440:         for (int i = 0; i < 400 && T.shm->session_ready != sg; i++) usleep(5000);
1441:         if (T.shm->session_ready != sg || T.shm->session_status != 0) {
1442:             if (!always) Arm(false);
1443:             return RmFastTrapPulse83de();
1444:         }
1445:     }
1446: 
1447:     uint32_t gen = T.shm->trigger_req + 1;
1448:     T.shm->trigger_req = gen;
1449:     for (int i = 0; i < 40 && T.shm->trigger_ack != gen; i++) usleep(1000);
1450:     if (!always) usleep(20000);
1451: 
1452:     bool hold = getenv("L3AGENT_HOLD") != nullptr ||
1453:                 getenv("XSCHED_SM120_TRAP_KEEP_SESSION") != nullptr;
1454:     if (lazy && !hold) {
1455:         uint32_t fg = T.shm->session_free_req + 1;
1456:         T.shm->session_free_req = fg;
1457:         for (int i = 0; i < 20 && T.shm->session_free_ack != fg; i++) usleep(1000);
1458:     }
1459:     if (!always) Arm(false);
1460:     return true;
1461: }
