1463: bool TrapSm120Context::Resume()
1464: {
1465:     if (T.shm == nullptr || T.shm->agent_ready == 0) {
1466:         Sm120RmCtxHandles h{};
1467:         if (!GetRmHandlesByIndex(target_slot_, &h)) {
1468:             GetLatestRmHandles(&h);
1469:         }
1470:         int fd = (h.ctl_fd >= 0) ? h.ctl_fd : H.fd;
1471:         uint32_t hClient = h.hClient ? h.hClient : H.client;
1472:         uint32_t hTsg = h.hTsg ? h.hTsg : H.tsg;
1473:         uint32_t hSession = h.hDebugger ? h.hDebugger : H.session;
1474:         uint32_t hDbgClient = h.hDebuggerClient ? h.hDebuggerClient : (H.dbg_client ? H.dbg_client : hClient);
1475:         if (fd >= 0 && hTsg != 0) {
1476:             struct { uint64_t timesliceUs; } ts{2000ULL};
1477:             rm_control(fd, hClient, hTsg, 0xa06c0103u, &ts, sizeof ts);
1478:         }
1479:         if (fd >= 0 && hSession != 0) {
1480:             uint32_t dummy = 0;
1481:             return rm_control(fd, hDbgClient, hSession, 0x83de0318u, &dummy, sizeof dummy) == 0;
1482:         }
1483:         return true;
1484:     }
1485:     uint32_t gen = T.shm->resume_req + 1;
1486:     T.shm->resume_req = gen;
1487:     for (int i = 0; i < 400 && T.shm->resume_ack != gen; i++) usleep(5000);
1488:     bool ok = T.shm->resume_ack == gen;
1489:     if (ok && getenv("XSCHED_SM120_TRAP_FREE_AFTER_RESUME") != nullptr) {
1490:         uint32_t fg = T.shm->session_free_req + 1;
1491:         T.shm->session_free_req = fg;
1492:         for (int i = 0; i < 100 && T.shm->session_free_ack != fg; i++) usleep(1000);
1493:     }
1494:     return ok;
1495: }
