21:                                       volatile unsigned long long *t_last,
22:                                       unsigned long long *atomic_accum,
23:                                       unsigned int *out_checksums,
24:                                       unsigned int total_iters) {
25:     unsigned int tid = blockIdx.x * blockDim.x + threadIdx.x;
26:     unsigned int state = tid * 0x9e3779b9u + 0x12345678u;
